function buildAttrs(pos,ovr,name){
 const h=Math.abs(hash(name)); const jitter=i=>((h>>(i%12))%9)-4;
 let a={vel:ovr-4+jitter(1),fin:ovr-8+jitter(2),pas:ovr-5+jitter(3),dri:ovr-5+jitter(4),def:ovr-8+jitter(5),fis:ovr-3+jitter(6),gk:25+jitter(7)};
 if(pos==='GOL')a={vel:ovr-25,fin:20,pas:ovr-15,dri:ovr-24,def:ovr-18,fis:ovr-4,gk:ovr+2};
 if(['ZAG'].includes(pos)){a.def+=8;a.fis+=6;a.fin-=9;a.dri-=6}
 if(['LD','LE'].includes(pos)){a.vel+=6;a.def+=3;a.pas+=2;a.fin-=5}
 if(pos==='VOL'){a.def+=6;a.pas+=5;a.fis+=3;a.fin-=4}
 if(pos==='MC'){a.pas+=7;a.dri+=2;a.def+=1}
 if(['MLE','MLD'].includes(pos)){a.vel+=5;a.pas+=4;a.dri+=3;a.def-=2}
 if(pos==='MAT'){a.pas+=7;a.dri+=6;a.fin+=4;a.def-=7}
 if(['PE','PD'].includes(pos)){a.vel+=8;a.dri+=7;a.fin+=3;a.def-=9}
 if(pos==='ATA'){a.fin+=9;a.fis+=3;a.def-=12;a.pas-=2}
 Object.keys(a).forEach(k=>a[k]=clamp(Math.round(a[k]),20,95));return a;
}
function derivePositions(p){
 const s=new Set([p.pos]); const a=p.attrs;
 if(p.pos==='GOL')return ['GOL'];
 if(p.pos==='ZAG'&&a.vel>=70){if((Math.abs(hash(p.name))%2)===0)s.add('LD');else s.add('LE')}
 if(['LD','LE'].includes(p.pos)){s.add('ZAG'); if(a.pas>=70)s.add(p.pos==='LD'?'MLD':'MLE')}
 if(p.pos==='VOL'&&a.pas>=68)s.add('MC');
 if(p.pos==='MC'){if(a.def>=72)s.add('VOL');if(a.fin>=72)s.add('MAT')}
 if(p.pos==='MAT'){s.add('MC');if(a.fin>=77)s.add('ATA')}
 if(p.pos==='MLE'){s.add('PE');if(a.def>=68)s.add('LE')}
 if(p.pos==='MLD'){s.add('PD');if(a.def>=68)s.add('LD')}
 if(p.pos==='PE'){s.add('MLE');if(a.fin>=78)s.add('ATA');if(a.dri>=80)s.add('PD')}
 if(p.pos==='PD'){s.add('MLD');if(a.fin>=78)s.add('ATA');if(a.dri>=80)s.add('PE')}
 if(p.pos==='ATA'&&a.dri>=75){s.add((Math.abs(hash(p.name))%2)?'PE':'PD');if(a.pas>=76)s.add('MAT')}
 return [...s];
}
function makeCorePlayer(club,raw,idx){
 const age=clamp(18+(Math.abs(hash(raw.name+club.id))%16),18,35),ovr=raw.ovr||clamp(club.rep+rnd(-6,5),58,86),attrs=buildAttrs(raw.pos,ovr,raw.name);
 const p={id:`${club.id}_${slug(raw.name)}_${idx}`,clubId:club.id,name:raw.name,age,pos:raw.pos,ovr,pot:clamp(ovr+(age<24?rnd(3,10):age>30?rnd(0,2):rnd(1,5)),ovr,93),attrs,value:Math.round(Math.max(250000,(ovr-50)*(ovr-50)*48000*(age<24?1.25:1))),wage:Math.round(ovr*ovr*10.5),contract:1+(Math.abs(hash(raw.name))%4),morale:74+(Math.abs(hash(raw.name))%20),fitness:90+(Math.abs(hash(raw.name+'fit'))%11),form:68+(Math.abs(hash(raw.name+'form'))%23),status:idx<11?'Titular':idx<17?'Rotação':'Reserva',generated:false,unhappy:false,listed:false,loanFrom:null,season:{apps:0,goals:0,assists:0,ratingSum:0,ratingApps:0,cards:0},compStats:{},career:{apps:0,goals:0,assists:0}};
 p.positions=derivePositions(p);const ranked=Object.entries(attrs).filter(([k])=>k!=='gk'||p.pos==='GOL').sort((a,b)=>b[1]-a[1]);p.traits=[labelAttr(ranked[0][0]),labelAttr(ranked[1][0])];return p;
}
function labelAttr(k){return({vel:'Velocidade',fin:'Finalização',pas:'Passe',dri:'Drible',def:'Marcação',fis:'Força',gk:'Reflexos'})[k]||k}
function makeGeneratedPlayer(club,idx,slot){
 const seed=Math.abs(hash(club.id+'academy'+idx)),name=`${GEN_FIRST[seed%GEN_FIRST.length]} ${GEN_LAST[(seed>>3)%GEN_LAST.length]}`,age=17+(seed%13),base=clamp(club.rep-8+(seed%12),54,80),attrs=buildAttrs(slot,base,name+' academy');
 const p={id:`${club.id}_base_${idx}`,clubId:club.id,name,age,pos:slot,ovr:base,pot:clamp(base+(age<22?6+(seed%8):2+(seed%4)),base,89),attrs,value:Math.round(Math.max(120000,(base-48)*(base-48)*26000)),wage:Math.round(base*base*6.5),contract:2+(seed%3),morale:70+(seed%24),fitness:88+(seed%13),form:64+(seed%25),status:'Base',generated:true,unhappy:false,listed:false,loanFrom:null,season:{apps:0,goals:0,assists:0,ratingSum:0,ratingApps:0,cards:0},compStats:{},career:{apps:0,goals:0,assists:0}};
 p.positions=derivePositions(p);const ranked=Object.entries(attrs).sort((a,b)=>b[1]-a[1]);p.traits=[labelAttr(ranked[0][0]),labelAttr(ranked[1][0])];return p;
}
function buildDatabase(){
 const clubs=BASE_DATA.clubs.map(c=>({...c})),players=[];
 clubs.forEach(c=>{
   const core=(BASE_DATA.rosters[c.id]||[]);core.forEach((r,i)=>players.push(makeCorePlayer(c,r,i)));
   if(c.guest){for(let i=0;i<24;i++)players.push(makeGeneratedPlayer(c,i,FILL_POS[i%FILL_POS.length]));return}
   let i=core.length;while(players.filter(p=>p.clubId===c.id).length<24){players.push(makeGeneratedPlayer(c,i,FILL_POS[i%FILL_POS.length]));i++}
 });
 return {clubs,players};
}
