function autoLineup(cid,formation='4-2-3-1',poolOverride=null){
 const slots=FORMS[formation],pool=(poolOverride||teamPlayers(cid)).slice(),used=new Set(),xi=[];
 slots.forEach((s,idx)=>{let candidates=pool.filter(p=>!used.has(p.id)&&canPlay(p,s.p)).sort((a,b)=>(b.ovr*posFit(b,s.p)+b.form/20)-(a.ovr*posFit(a,s.p)+a.form/20));let p=candidates[0];if(!p){p=pool.filter(x=>!used.has(x.id)&&x.pos!=='GOL'&&s.p!=='GOL').sort((a,b)=>b.ovr-a.ovr)[0]||pool.filter(x=>!used.has(x.id)).sort((a,b)=>b.ovr-a.ovr)[0]}if(p){used.add(p.id);xi.push({slotPos:s.p,x:s.x,y:s.y,playerId:p.id})}});
 const rest=pool.filter(p=>!used.has(p.id)).sort((a,b)=>b.ovr-a.ovr),bench=rest.slice(0,9).map(p=>p.id),out=rest.slice(9).map(p=>p.id);return {formation,xi,bench,out};
}

function makeLeagueTable(ids){return ids.map(id=>({clubId:id,p:0,w:0,d:0,l:0,gf:0,ga:0,gd:0,pts:0}))}
function createRoundRobin(ids,compId,startDate,double=true){
 let arr=ids.slice();if(arr.length%2)arr.push(null);const n=arr.length,rounds=[];
 for(let r=0;r<n-1;r++){
   const pairs=[];for(let i=0;i<n/2;i++){let a=arr[i],b=arr[n-1-i];if(a&&b){const flip=(r+i)%2===1;pairs.push(flip?[b,a]:[a,b])}}
   rounds.push(pairs);arr=[arr[0],arr[n-1],...arr.slice(1,n-1)];
 }
 const fs=[];rounds.forEach((pairs,r)=>pairs.forEach(([h,a],i)=>fs.push({id:uid(),compId,date:addDays(startDate,r*7),round:r+1,home:h,away:a,played:false,score:null})));
 if(double)rounds.forEach((pairs,r)=>pairs.forEach(([h,a])=>fs.push({id:uid(),compId,date:addDays(startDate,(r+n-1)*7),round:r+n,home:a,away:h,played:false,score:null})));
 return fs;
}
function createCup(stateObj,startDate){
 const br=stateObj.db.clubs.filter(c=>!c.guest),ranked=br.slice().sort((a,b)=>b.rep-a.rep),ids=ranked.slice(0,32).map(c=>c.id);if(!ids.includes(stateObj.clubId))ids[31]=stateObj.clubId;shuffle(ids);stateObj.competitions.copa={id:'copa',name:'Copa Nacional',type:'cup',clubIds:ids.slice(),roundName:'Fase de 32',activeIds:ids.slice(),finished:false,champion:null};createCupRound(stateObj,ids,'Fase de 32',startDate)}
