function maybeAdvanceCup(){
 const c=state.competitions.copa;if(!c||c.finished)return;const current=state.fixtures.filter(f=>f.compId==='copa'&&f.round===c.roundName);if(!current.length||current.some(f=>!f.played))return;
 const winners=current.map(f=>f.winnerId);if(winners.length===1){c.finished=true;c.champion=winners[0];c.activeIds=winners;state.news.push({date:state.date,title:'Campeão da Copa Nacional',body:`${club(winners[0]).name} conquistou a Copa Nacional.`});return}
 const names={16:'Oitavas',8:'Quartas',4:'Semifinal',2:'Final'},nextName=names[winners.length]||`Fase de ${winners.length}`;createCupRound(state,winners,nextName,addDays(current[0].date,28));
}
