function currentStanding(){const c=club(state.clubId),cid=c.division==='A'?'brA':'brB',t=sortedTable(cid),i=t.findIndex(r=>r.clubId===c.id);return i>=0?{...t[i],pos:i+1}:null}
function ratingClass(n){return n>=85?'r85':n>=78?'r78':n>=70?'r70':'r60'}

function renderSquad(){const ps=teamPlayers(state.clubId).slice().sort((a,b)=>b.ovr-a.ovr);let sel=player(state.selectedPlayer)||ps[0];state.selectedPlayer=sel?.id;$('#squad').innerHTML=`<div class="page-head"><div><h1>Elenco</h1><p>${ps.length} jogadores • ${ps.filter(p=>!p.generated).length} do núcleo real • banco 30/09/2026</p></div><span class="tag">${state.season}</span></div><div class="split"><div class="card" style="padding:0"><div class="table-wrap" style="border:0"><table class="table"><thead><tr><th>Pos</th><th>Jogador</th><th>Posições</th><th>Idade</th><th>OVR</th><th>POT</th><th>Físico</th><th>Moral</th><th>Contrato</th></tr></thead><tbody>${ps.map(p=>`<tr class="clickable" onclick="selectPlayer('${p.id}','squad')"><td><span class="pos">${p.pos}</span></td><td><b>${p.name}</b>${p.generated?'<div class="tiny muted">Base gerada</div>':''}</td><td>${p.positions.join(' / ')}</td><td>${p.age}</td><td class="rating ${ratingClass(p.ovr)}">${p.ovr}</td><td>${p.pot}</td><td>${p.fitness}%</td><td>${p.morale}%</td><td>${p.contract}a</td></tr>`).join('')}</tbody></table></div></div><div class="card player-panel" id="playerPanel">${playerDetail(sel)}</div></div>`}
window.selectPlayer=(pid,page)=>{state.selectedPlayer=pid;save();if(page==='squad')$('#playerPanel').innerHTML=playerDetail(player(pid));else renderTactics()};
function avgRating(p){return p.season.ratingApps?p.season.ratingSum/p.season.ratingApps:0}
function playerDetailBaseV02(p){if(!p)return '<p class="muted">Selecione um jogador.</p>';const sug=teamPlayers(state.clubId).filter(x=>x.id!==p.id&&canPlay(x,p.pos)).sort((a,b)=>b.ovr-a.ovr).slice(0,5);return `<div class="player-top"><div class="avatar">${p.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><h2 style="margin:0;font-size:19px">${p.name}</h2><div class="muted small">${p.age} anos • ${p.positions.join(' / ')}</div>${p.generated?'<span class="tag" style="margin-top:5px">Base / jogador gerado</span>':'<span class="tag" style="margin-top:5px">Elenco principal</span>'}</div></div><div class="grid grid-3" style="margin:15px 0"><div><div class="metric">${p.ovr}</div><div class="metric-label">OVR</div></div><div><div class="metric">${p.pot}</div><div class="metric-label">Potencial</div></div><div><div class="metric">${avgRating(p)?avgRating(p).toFixed(2):'—'}</div><div class="metric-label">Nota média</div></div></div><h3>Atributos</h3><div class="attr-grid">${Object.entries(p.attrs).filter(([k])=>p.pos==='GOL'||k!=='gk').map(([k,v])=>`<div class="attr"><span>${labelAttr(k)}</span><b>${v}</b></div>`).join('')}</div><h3 style="margin-top:15px">Características</h3><div class="traits">${p.traits.map(t=>`<span class="trait">${t}</span>`).join('')}</div><h3 style="margin-top:15px">Temporada</h3><div class="small"><b>${p.season.apps}</b> jogos • <b>${p.season.goals}</b> gols • <b>${p.season.assists}</b> assistências</div><div class="tiny muted" style="margin-top:4px">Valor ${brl(p.value)} • salário ${brl(p.wage)}/mês • contrato ${p.contract} ano(s)</div><h3 style="margin-top:15px">Substitutos compatíveis</h3>${sug.map(x=>`<div class="suggestion"><b>${x.name}</b><div class="tiny muted">${x.positions.join(' / ')} • OVR ${x.ovr}</div></div>`).join('')||'<div class="muted tiny">Nenhum substituto natural.</div>'}`}

function renderTactics(){
 const lu=state.lineup;if(!lu||lu.formation!==state.formation)state.lineup=autoLineup(state.clubId,state.formation);const sel=player(state.selectedPlayer)||player(state.lineup.xi[0]?.playerId);state.selectedPlayer=sel?.id;const target=state.tacticTarget;
 $('#tactics').innerHTML=`<div class="page-head"><div><h1>Táticas</h1><p>Selecione um slot no campo e escolha um jogador compatível dos reservas/não relacionados.</p></div><div style="width:180px"><select id="formationSelect">${Object.keys(FORMS).map(f=>`<option ${f===state.formation?'selected':''}>${f}</option>`).join('')}</select></div></div><div class="grid" style="grid-template-columns:minmax(0,1.1fr) minmax(330px,.9fr)"><div class="card"><div class="pitch"><div class="center-circle"></div>${state.lineup.xi.map((s,i)=>{const p=player(s.playerId);return `<div class="slot ${target===i?'target':''}" style="left:${s.x}%;top:${s.y}%"><button onclick="targetSlot(${i});selectPlayer('${p.id}','tactics')"><div class="slot-bubble">${s.slotPos}</div><small>${p.name} • ${p.ovr}</small></button></div>`}).join('')}</div><div class="grid grid-3" style="margin-top:10px"><div><label class="tiny muted">Pressão</label><input type="range" min="20" max="90" value="${state.pressing}" id="pressing"></div><div><label class="tiny muted">Linha defensiva</label><input type="range" min="20" max="90" value="${state.line}" id="line"></div><div><label class="tiny muted">Ritmo</label><input type="range" min="20" max="90" value="${state.tempo}" id="tempo"></div></div></div><div class="grid"><div class="card"><h3>Reservas ${target!==null?`• compatíveis com ${state.lineup.xi[target].slotPos}`:''}</h3><div class="bench-grid">${state.lineup.bench.map(id=>tacticChip(id,'bench',target)).join('')}</div><h3 style="margin-top:14px">Não relacionados</h3><div class="bench-grid">${state.lineup.out.map(id=>tacticChip(id,'out',target)).join('')}</div></div><div class="card player-panel" style="position:static">${playerDetail(sel)}</div></div></div>`;
 $('#formationSelect').onchange=e=>{state.formation=e.target.value;state.lineup=autoLineup(state.clubId,state.formation);state.tacticTarget=null;save();renderTactics()};['pressing','line','tempo'].forEach(id=>{$('#'+id).onchange=e=>{state[id]=+e.target.value;save()}})
}
function tacticChip(id,area,target){const p=player(id),slot=target!==null?state.lineup.xi[target].slotPos:null,ok=target===null||canPlay(p,slot);return `<div class="player-chip" onclick="selectPlayer('${p.id}','tactics')"><span class="pos">${p.pos}</span><div class="grow"><b>${p.name}</b><span class="tiny muted">OVR ${p.ovr} • ${p.positions.join('/')}</span></div>${target!==null?`<button ${ok?'':'disabled'} onclick="event.stopPropagation();placeInSlot('${p.id}',${target},'${area}')">Escalar</button>`:''}</div>`}
window.targetSlot=i=>{state.tacticTarget=state.tacticTarget===i?null:i;renderTactics()};
window.placeInSlot=(pid,idx,area)=>{const slot=state.lineup.xi[idx];const p=player(pid);if(!canPlay(p,slot.slotPos))return toast(`${p.name} não pode jogar em ${slot.slotPos}.`);const old=slot.playerId;slot.playerId=pid;const arr=state.lineup[area];arr[arr.indexOf(pid)]=old;state.selectedPlayer=pid;state.tacticTarget=null;save();renderTactics();toast(`${p.name} escalado em ${slot.slotPos}.`)};

function sortedTable(cid){const c=comp(cid);if(!c?.table)return[];return c.table.slice().sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf)}
function tableHtml(cid,mini=false){const c=comp(cid);if(!c)return'';if(c.type==='cup')return cupHtml(mini);const t=sortedTable(cid),n=t.length;return `<div class="table-wrap ${mini?'mini-table':''}"><table class="table"><thead><tr><th>#</th><th>Clube</th><th>Pts</th>${mini?'':'<th>J</th><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th>'}<th>SG</th></tr></thead><tbody>${t.map((r,i)=>{let cls='';if(!c.continental&&cid==='brA'){if(i===0)cls='champion';else if(i<=3)cls='libertadores';else if(i<=7)cls='sudamericana';else if(i>=n-4)cls='relegated'}if(cid==='brB'){if(i<=3)cls='libertadores'}return `<tr class="${cls}"><td>${i+1}</td><td><b>${club(r.clubId).abbr}</b>${mini?'':` <span class="tiny muted">${club(r.clubId).name}</span>`}</td><td><b>${r.pts}</b></td>${mini?'':`<td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gf}</td><td>${r.ga}</td>`}<td>${r.gf-r.ga>0?'+':''}${r.gf-r.ga}</td></tr>`}).join('')}</tbody></table></div>`}
function cupHtml(mini=false){const c=state.competitions.copa,fs=state.fixtures.filter(f=>f.compId==='copa'&&f.round===c.roundName);return `<div class="${mini?'mini-table':''}">${fs.map(f=>`<div class="fixture"><span class="tag">${c.roundName}</span><div class="teams"><b>${club(f.home).abbr} x ${club(f.away).abbr}</b><div class="tiny muted">${club(f.home).name} x ${club(f.away).name}</div></div><div class="score">${f.played?`${f.score.home}-${f.score.away}`:'—'}</div></div>`).join('')}${c.finished?`<div class="summary-hero"><b>🏆 Campeão: ${club(c.champion).name}</b></div>`:''}</div>`}
function compLeaders(cid,type){const ps=state.db.players.map(p=>({p,s:p.compStats[cid]})).filter(x=>x.s&&x.s.apps>0);if(type==='goals')return ps.sort((a,b)=>b.s.goals-a.s.goals||b.s.assists-a.s.assists).slice(0,5);if(type==='assists')return ps.sort((a,b)=>b.s.assists-a.s.assists||b.s.goals-a.s.goals).slice(0,5);return ps.filter(x=>x.s.ratingApps>0).sort((a,b)=>(b.s.ratingSum/b.s.ratingApps)-(a.s.ratingSum/a.s.ratingApps)).slice(0,5)}
function leadersBlock(cid,type,title){const list=compLeaders(cid,type);return `<div class="card"><h3>${title}</h3><div class="leaders">${list.map((x,i)=>{const v=type==='goals'?x.s.goals:type==='assists'?x.s.assists:(x.s.ratingSum/x.s.ratingApps).toFixed(2);return `<div class="leader"><div class="rank">${i+1}</div><div class="grow"><b>${x.p.name}</b><div class="tiny muted">${x.p.age} anos • ${club(x.p.clubId).name}</div></div><b>${v}</b></div>`}).join('')||'<p class="muted tiny">Ainda sem dados suficientes.</p>'}</div></div>`}
function renderCompetitions(){const ids=Object.keys(state.competitions),sel=state.selectedCompetition&&state.competitions[state.selectedCompetition]?state.selectedCompetition:(club(state.clubId).division==='A'?'brA':'brB');state.selectedCompetition=sel;const c=comp(sel);$('#competitions').innerHTML=`<div class="page-head"><div><h1>Competições</h1><p>Classificação, artilharia, assistências e melhor nota média.</p></div><div style="width:260px"><select id="compSelect">${ids.map(id=>`<option value="${id}" ${id===sel?'selected':''}>${state.competitions[id].name}</option>`).join('')}</select></div></div><div class="comp-layout"><div class="card"><div style="display:flex;justify-content:space-between;align-items:center"><h3 style="margin:0">${c.name}</h3><span class="tag">${c.type==='cup'?c.roundName:'Classificação'}</span></div><div style="margin-top:11px">${tableHtml(sel)}</div>${sel==='brA'?'<div class="legend"><span><i class="swatch green"></i>Campeão</span><span><i class="swatch blue"></i>2º–4º Continental</span><span><i class="swatch purple"></i>5º–8º Continental B</span><span><i class="swatch red"></i>Rebaixamento</span></div>':''}</div><div class="grid">${leadersBlock(sel,'goals','⚽ Artilharia')}${leadersBlock(sel,'assists','🎯 Assistências')}${leadersBlock(sel,'rating','⭐ Melhor nota média')}</div></div>`;$('#compSelect').onchange=e=>{state.selectedCompetition=e.target.value;save();renderCompetitions()}}
window.openCompetition=id=>{state.selectedCompetition=id;showPage('competitions')};

function renderMatch(){
 const f=nextUserFixture();if(!f){$('#match').innerHTML=`<div class="page-head"><div><h1>Partida</h1><p>Sem jogo pendente.</p></div></div><div class="card">${state.offseason?.active?'A temporada terminou. Use o período de transferências antes da próxima temporada.':'Não há partida agendada.'}</div>`;return}
 const h=club(f.home),a=club(f.away),m=state.match&&state.match.fixtureId===f.id?state.match:null,c=comp(f.compId);$('#match').innerHTML=`<div class="page-head"><div><h1>${c.name}</h1><p>${fmtDate(f.date)}${f.round?` • ${f.round}`:''} • ${m?.userFormation||state.formation}</p></div><div style="display:flex;gap:7px"><button onclick="openCompetition('${f.compId}')">Ver competição</button>${m&&!m.finished?'<span class="tag">● AO VIVO</span>':''}</div></div><div class="card scoreboard"><div class="team-score"><div class="name">${h.name}</div><div class="score" id="homeScore">${m?m.home:0}</div></div><div class="clock" id="matchClock">${m?m.minute:0}'</div><div class="team-score"><div class="name">${a.name}</div><div class="score" id="awayScore">${m?m.away:0}</div></div></div><div class="match-layout"><div class="card"><div class="match-pitch" id="matchPitch"><div class="midline"></div><div class="circle"></div>${pitchDots()}<div class="ball" id="ball" style="left:50%;top:50%"></div></div><div class="match-controls" style="margin-top:10px"><button onclick="setLiveMentality('Defensivo')">🛡 Defensivo</button><button onclick="setLiveMentality('Equilibrado')">⚖ Equilibrado</button><button onclick="setLiveMentality('Ofensivo')">⚔ Ofensivo</button><button onclick="openSubs(false)" ${!m?'disabled':''}>🔄 Substituições / Formação</button></div></div><div class="grid"><div class="card"><h3>Ações</h3><div class="match-controls"><button class="primary" onclick="startMatch()">${m&&!m.finished?'Continuar':m&&m.finished?'Encerrado':'Iniciar jogo'}</button><button onclick="speedMatch()">⏩ Rápido</button><button onclick="pauseMatch()">⏸ Pausar</button></div>${m?`<div class="tiny muted" style="margin-top:8px">Subs: ${m.subsUsed}/5 • janelas: ${m.windowsUsed}/3</div>`:''}</div><div class="card"><h3>Estatísticas</h3><div id="matchStats">${statsHtml(m)}</div></div><div class="card"><h3>Cansaço acumulado</h3><div id="fatigueList">${fatigueHtml(m)}</div></div><div class="card"><h3>${c.type==='cup'?'Chave atual':'Classificação ao vivo'}</h3>${tableHtml(f.compId,true)}</div><div class="card"><h3>Comentários</h3><div class="commentary" id="commentary">${(m?.comments||[]).slice().reverse().map(x=>`<div class="comment"><b>${x.min}'</b> ${x.text}</div>`).join('')}</div></div></div></div>`
}
function pitchDots(){let out='';for(let i=0;i<11;i++){out+=`<span class="dot-player home" id="h${i}" style="left:${10+(i%4)*9}%;top:${12+(i*7)%80}%"></span><span class="dot-player away" id="a${i}" style="left:${58+(i%4)*9}%;top:${12+(i*7)%80}%"></span>`}return out}
function statsHtml(m){const s=m?.stats||{posH:50,posA:50,shotsH:0,shotsA:0,onH:0,onA:0,xgH:0,xgA:0};return `<div class="stat-row"><span>${s.posH}%</span><div class="bar"><span style="width:${s.posH}%"></span></div><span>${s.posA}%</span></div><div class="tiny muted" style="text-align:center">Posse</div><div class="stat-row"><span>${s.shotsH}</span><div class="tiny">Finalizações</div><span>${s.shotsA}</span></div><div class="stat-row"><span>${s.onH}</span><div class="tiny">No alvo</div><span>${s.onA}</span></div><div class="stat-row"><span>${s.xgH.toFixed(1)}</span><div class="tiny">xG</div><span>${s.xgA.toFixed(1)}</span></div>`}
function fatigueHtml(m){if(!m)return '<p class="muted tiny">O cansaço começa a ser calculado ao iniciar a partida.</p>';return m.userXI.map(s=>{const p=player(s.playerId),v=Math.round(m.fatigue[p.id]||0),cls=v>=70?'high':v>=45?'mid':'';return `<div class="fatigue-line"><span><b>${p.name}</b> <span class="tiny muted">${s.slotPos}</span></span><span class="fatigue-badge ${cls}">${v}%</span></div>`}).join('')}
window.setLiveMentality=v=>{state.mentality=v;if(state.match)state.match.mentality=v;save();toast('Mentalidade: '+v)};
window.startMatch=()=>{const f=nextUserFixture();if(!f)return;if(state.date<f.date){simulateUntil(f.date,f.id);state.date=f.date}if(!state.match||state.match.fixtureId!==f.id){const userHome=f.home===state.clubId,oppId=userHome?f.away:f.home,ai=autoLineup(oppId,'4-2-3-1');state.match={fixtureId:f.id,minute:0,home:0,away:0,userHome,userFormation:state.formation,userXI:JSON.parse(JSON.stringify(state.lineup.xi)),userBench:state.lineup.bench.slice(),aiXI:ai.xi,mentality:state.mentality,stats:{posH:50,posA:50,shotsH:0,shotsA:0,onH:0,onA:0,xgH:0,xgA:0},comments:[{min:0,text:'A bola está rolando!'}],goalEvents:[],fatigue:{},participants:state.lineup.xi.map(s=>s.playerId),subbedOut:[],subsUsed:0,windowsUsed:0,subModal:null,halfTimeDone:false,finished:false,speed:650};state.match.userXI.forEach(s=>state.match.fatigue[s.playerId]=0)}runMatch();renderMatch()};
function runMatch(){clearInterval(matchTimer);if(!state.match||state.match.finished||state.match.subModal)return;matchTimer=setInterval(matchStep,state.match.speed||650)}
window.pauseMatch=()=>{clearInterval(matchTimer);toast('Partida pausada.')};window.speedMatch=()=>{if(!state.match)return;state.match.speed=150;runMatch();toast('Velocidade rápida.')};
function matchTeamStrength(cid){const m=state.match;let slots;if(m&&cid===state.clubId)slots=m.userXI;else if(m&&((m.userHome&&cid===state.fixtures.find(f=>f.id===m.fixtureId).away)||(!m.userHome&&cid===state.fixtures.find(f=>f.id===m.fixtureId).home)))slots=m.aiXI;else slots=autoLineup(cid).xi;return slots.reduce((s,x)=>{const p=player(x.playerId),fat=cid===state.clubId?(m.fatigue[p.id]||0):m?.minute*.42||0;return s+p.ovr*posFit(p,x.slotPos)*(1-clamp(fat,0,90)/190)*(.82+p.morale/500)},0)/Math.max(1,slots.length)}
function scorerFor(cid){const m=state.match,slots=cid===state.clubId?m.userXI:m.aiXI,weighted=[];slots.forEach(s=>{const p=player(s.playerId),w=Math.max(1,p.attrs.fin-45)+(p.pos==='ATA'?28:['PE','PD','MAT'].includes(p.pos)?14:0);for(let i=0;i<Math.max(1,Math.round(w/8));i++)weighted.push(p)});return pick(weighted)||player(slots[0].playerId)}
function assistFor(cid,scorerId){const m=state.match,slots=cid===state.clubId?m.userXI:m.aiXI,cands=slots.map(s=>player(s.playerId)).filter(p=>p.id!==scorerId).sort((a,b)=>(b.attrs.pas+b.attrs.dri)-(a.attrs.pas+a.attrs.dri));return Math.random()<.82?pick(cands.slice(0,5)):null}
function matchStep(){
 const m=state.match,f=state.fixtures.find(x=>x.id===m.fixtureId);if(!m||m.finished||m.subModal)return;m.minute++;m.userXI.forEach(s=>{const p=player(s.playerId),inc=.38+state.pressing/260+state.tempo/330+(p.attrs.fis<70?.08:0)+Math.random()*.08;m.fatigue[p.id]=clamp((m.fatigue[p.id]||0)+inc,0,100)});animatePitch();const hs=matchTeamStrength(f.home),as=matchTeamStrength(f.away),meHome=f.home===state.clubId;let tact=m.mentality==='Ofensivo'?.06:m.mentality==='Defensivo'?-.04:0,myMod=(state.pressing-55)/320+(state.tempo-55)/360+(state.line-50)/650;let attH=hs*(1+(meHome?tact+myMod:0)),attA=as*(1+(!meHome?tact+myMod:0)),pH=attH/(attH+attA);m.stats.posH=clamp(Math.round(45+(pH-.5)*65+rnd(-2,2)),33,67);m.stats.posA=100-m.stats.posH;
 if(Math.random()<.145+(state.tempo-50)/900){const homeAttack=Math.random()<pH,att=homeAttack?attH:attA,def=homeAttack?as:hs,quality=(att/Math.max(1,def))*Math.random(),s=m.stats;homeAttack?s.shotsH++:s.shotsA++;const xg=clamp(.035+quality*.17+Math.random()*.12,.03,.42);homeAttack?s.xgH+=xg:s.xgA+=xg;const on=Math.random()<.40+quality*.14;if(on){homeAttack?s.onH++:s.onA++;if(Math.random()<xg*(.72+Math.random()*.25)){homeAttack?m.home++:m.away++;const cid=homeAttack?f.home:f.away,sc=scorerFor(cid),asst=assistFor(cid,sc.id);m.goalEvents.push({min:m.minute,clubId:cid,scorerId:sc.id,assistId:asst?.id||null});m.comments.push({min:m.minute,text:`GOL do ${club(cid).name}! ${sc.name}${asst?` recebeu de ${asst.name}`:''} e marcou.`});toast(`⚽ ${sc.name} — ${club(cid).abbr}`)}else if(Math.random()<.42)m.comments.push({min:m.minute,text:'Defesa importante do goleiro.'})}else if(Math.random()<.30)m.comments.push({min:m.minute,text:'Finalização para fora.'})}
 if(m.minute===45&&!m.halfTimeDone){m.halfTimeDone=true;m.comments.push({min:45,text:'Intervalo. A partida foi pausada para ajustes.'});state.match=m;save();updateMatchDom();openSubs(true);return}if(m.minute>=90){finishMatch();return}state.match=m;save();updateMatchDom()
}
function animatePitch(){for(let i=0;i<11;i++){const h=$('#h'+i),a=$('#a'+i);if(h){h.style.left=rnd(8,61)+'%';h.style.top=rnd(8,92)+'%'}if(a){a.style.left=rnd(39,92)+'%';a.style.top=rnd(8,92)+'%'}}const b=$('#ball');if(b){b.style.left=rnd(10,90)+'%';b.style.top=rnd(10,90)+'%'}}
function updateMatchDom(){const m=state.match;if(!m)return;$('#homeScore')&&($('#homeScore').textContent=m.home);$('#awayScore')&&($('#awayScore').textContent=m.away);$('#matchClock')&&($('#matchClock').textContent=m.minute+"'");$('#matchStats')&&($('#matchStats').innerHTML=statsHtml(m));$('#fatigueList')&&($('#fatigueList').innerHTML=fatigueHtml(m));$('#commentary')&&($('#commentary').innerHTML=m.comments.slice().reverse().map(x=>`<div class="comment"><b>${x.min}'</b> ${x.text}</div>`).join(''))}

window.openSubs=openSubs;
function openSubs(halftime=false){const m=state.match;if(!m||m.finished)return;clearInterval(matchTimer);m.subModal={halftime,changesInWindow:0,selectedOut:null};state.match=m;save();renderSubModal()}
function renderSubModal(){const m=state.match;if(!m?.subModal)return;modal(`<div class="modal-head"><div><h2>🔄 Substituições e formação</h2><div class="tiny muted">${m.subModal.halftime?'Intervalo — esta parada não conta como janela.':`5 substituições • 3 janelas • usadas: ${m.subsUsed}/5 e ${m.windowsUsed}/3`}</div></div><button onclick="closeSubs()">✕</button></div><div class="field" style="max-width:240px"><label>Formação durante o jogo</label><select id="liveForm">${Object.keys(FORMS).map(f=>`<option ${f===m.userFormation?'selected':''}>${f}</option>`).join('')}</select></div><div class="sub-layout"><div><h3>Titulares</h3><div class="sub-list">${m.userXI.map((s,i)=>{const p=player(s.playerId),fat=Math.round(m.fatigue[p.id]||0);return `<div class="sub-row ${m.subModal.selectedOut===i?'selected':''}"><span class="pos">${s.slotPos}</span><div class="grow"><b>${p.name}</b><div class="tiny muted">OVR ${p.ovr} • cansaço ${fat}%</div></div><button onclick="chooseSubOut(${i})">${m.subModal.selectedOut===i?'Selecionado':'Sair'}</button></div>`}).join('')}</div></div><div><h3>Reservas</h3><div class="sub-list">${m.userBench.map(id=>{const p=player(id),target=m.subModal.selectedOut!==null?m.userXI[m.subModal.selectedOut].slotPos:null,ok=target?canPlay(p,target):false;return `<div class="sub-row"><span class="pos">${p.pos}</span><div class="grow"><b>${p.name}</b><div class="tiny muted">${p.positions.join('/')} • OVR ${p.ovr}</div></div><button ${ok?'':'disabled'} onclick="confirmSub('${p.id}')">Entrar</button></div>`}).join('')}</div></div></div><div style="display:flex;justify-content:flex-end;gap:7px;margin-top:13px"><button onclick="closeSubs()">Voltar ao jogo</button></div>`);$('#liveForm').onchange=e=>changeLiveFormation(e.target.value)}
window.chooseSubOut=i=>{state.match.subModal.selectedOut=i;renderSubModal()};
window.confirmSub=pid=>{const m=state.match,sm=m.subModal;if(sm.selectedOut===null)return toast('Escolha quem vai sair.');if(m.subsUsed>=5)return toast('Você já usou as 5 substituições.');if(!sm.halftime&&sm.changesInWindow===0&&m.windowsUsed>=3)return toast('Você já usou as 3 janelas de substituição.');const slot=m.userXI[sm.selectedOut],p=player(pid);if(!canPlay(p,slot.slotPos))return toast(`${p.name} não pode atuar em ${slot.slotPos}.`);if(!sm.halftime&&sm.changesInWindow===0)m.windowsUsed++;const old=slot.playerId,bi=m.userBench.indexOf(pid);slot.playerId=pid;m.userBench.splice(bi,1);m.subbedOut=m.subbedOut||[];m.subbedOut.push(old);m.fatigue[pid]=Math.max(0,(100-player(pid).fitness)*.2);m.participants.push(pid);m.subsUsed++;sm.changesInWindow++;sm.selectedOut=null;save();renderSubModal();toast(`${p.name} entrou no jogo.`)};
function changeLiveFormation(form){const m=state.match,current=m.userXI.map(s=>player(s.playerId)),newSlots=FORMS[form],used=new Set(),newXI=[];for(const s of newSlots){const cand=current.filter(p=>!used.has(p.id)&&canPlay(p,s.p)).sort((a,b)=>b.ovr-a.ovr)[0];if(!cand){toast(`Não é possível montar ${form} com as posições dos 11 atuais.`);renderSubModal();return}used.add(cand.id);newXI.push({slotPos:s.p,x:s.x,y:s.y,playerId:cand.id})}m.userFormation=form;m.userXI=newXI;save();toast('Formação alterada para '+form);renderSubModal()}
window.closeSubs=()=>{state.match.subModal=null;$('#modalRoot').innerHTML='';save();runMatch();renderMatch()};

function updatePlayerMatchStatsBaseV02(cid,compId,participants,result,gf,ga,goalEvents){
 const unique=[...new Set(participants)];unique.forEach(id=>{const p=player(id);if(!p)return;p.season.apps++;p.career.apps++;const cs=getCompStat(p,compId);cs.apps++;let base=6.25+(result==='win'?.55:result==='loss'?-.25:.1)+(p.ovr-70)/55+(Math.random()-.5)*.7;const rating=clamp(base,5.2,9.4);p.season.ratingSum+=rating;p.season.ratingApps++;cs.ratingSum+=rating;cs.ratingApps++});goalEvents.filter(g=>g.clubId===cid).forEach(g=>{const sc=player(g.scorerId);if(sc){sc.season.goals++;sc.career.goals++;getCompStat(sc,compId).goals++}const a=player(g.assistId);if(a){a.season.assists++;a.career.assists++;getCompStat(a,compId).assists++}})
}
function applyTableResult(f,homeGoals,awayGoals){const c=comp(f.compId);if(!c||c.type!=='league')return;const h=c.table.find(r=>r.clubId===f.home),a=c.table.find(r=>r.clubId===f.away);if(!h||!a)return;h.p++;a.p++;h.gf+=homeGoals;h.ga+=awayGoals;a.gf+=awayGoals;a.ga+=homeGoals;if(homeGoals>awayGoals){h.w++;a.l++;h.pts+=3}else if(homeGoals<awayGoals){a.w++;h.l++;a.pts+=3}else{h.d++;a.d++;h.pts++;a.pts++}h.gd=h.gf-h.ga;a.gd=a.gf-a.ga}
function finalizeFixtureResult(f,hg,ag,details=null){f.played=true;f.score={home:hg,away:ag};if(comp(f.compId)?.type==='cup'&&hg===ag){if(Math.random()<.5)hg++;else ag++;f.score={home:hg,away:ag,penalties:true}}f.winnerId=hg>ag?f.home:ag>hg?f.away:null;applyTableResult(f,hg,ag);if(comp(f.compId)?.type==='cup')maybeAdvanceCup();return f}
function finishMatchBaseV02(){
 clearInterval(matchTimer);const m=state.match,f=state.fixtures.find(x=>x.id===m.fixtureId);m.finished=true;let hg=m.home,ag=m.away;if(comp(f.compId)?.type==='cup'&&hg===ag){m.comments.push({min:90,text:'Empate no tempo normal. A vaga será decidida nos pênaltis.'});if(Math.random()<.5)hg++;else ag++;m.home=hg;m.away=ag}finalizeFixtureResult(f,hg,ag);const myHome=f.home===state.clubId,myGoals=myHome?hg:ag,oppGoals=myHome?ag:hg,result=myGoals>oppGoals?'win':myGoals<oppGoals?'loss':'draw';state.manager.played++;state.manager.gf+=myGoals;state.manager.ga+=oppGoals;if(result==='win')state.manager.wins++;else if(result==='loss')state.manager.losses++;else state.manager.draws++;const opp=club(myHome?f.away:f.home),repDiff=(opp.rep-club(state.clubId).rep)/1000;let delta=result==='win'?.035:result==='loss'?-.03:.008;delta+=result==='win'?Math.max(0,repDiff):result==='loss'?Math.min(0,repDiff):0;state.manager.rating=clamp(Math.round((state.manager.rating+delta)*100)/100,1,10);state.manager.seasonDelta=clamp(state.manager.seasonDelta+delta,-1,1);state.clubConfidence=clamp(state.clubConfidence+(result==='win'?4:result==='loss'?-5:1),0,100);
 const userParts=m.participants,aiParts=m.aiXI.map(s=>s.playerId),oppResult=result==='win'?'loss':result==='loss'?'win':'draw';updatePlayerMatchStats(state.clubId,f.compId,userParts,result,myGoals,oppGoals,m.goalEvents);updatePlayerMatchStats(opp.id,f.compId,aiParts,oppResult,oppGoals,myGoals,m.goalEvents);teamPlayers(state.clubId).forEach(p=>{if(userParts.includes(p.id)){p.fitness=clamp(p.fitness-Math.round((m.fatigue[p.id]||50)/7),38,100);p.morale=clamp(p.morale+(result==='win'?rnd(2,5):result==='loss'?-rnd(2,4):0),25,100)}else p.fitness=clamp(p.fitness+rnd(1,3),40,100)});
 state.news.push({date:state.date,title:`${result==='win'?'Vitorioso':result==='loss'?'Derrota':'Empate'}: ${club(f.home).name} ${hg} x ${ag} ${club(f.away).name}`,body:`Sua nota de técnico agora é ${state.manager.rating.toFixed(2)}.`});state.history.push({date:state.date,clubId:state.clubId,fixtureId:f.id,result,score:`${myGoals}-${oppGoals}`});state.lastMatch={...m,home:hg,away:ag};state.match=null;state.date=addDays(state.date,1);simulateUntil(state.date,null);checkSeasonEnd();save();renderAll();showPage('dashboard');toast(`Fim: ${club(f.home).abbr} ${hg} x ${ag} ${club(f.away).abbr}`)
}

function simulateFixture(f){if(f.played)return;const hs=genericStrength(f.home),as=genericStrength(f.away),ratio=hs/(hs+as),homeAdv=.05,lambdaH=clamp(.65+ratio*1.9+homeAdv,.45,2.7),lambdaA=clamp(.55+(1-ratio)*1.8,.4,2.5),hg=poisson(lambdaH),ag=poisson(lambdaA);finalizeFixtureResult(f,hg,ag);const hxi=autoLineup(f.home).xi.map(s=>s.playerId),axi=autoLineup(f.away).xi.map(s=>s.playerId),events=[];for(let i=0;i<hg;i++){const sc=weightedScorerGeneric(f.home,hxi),a=weightedAssistGeneric(f.home,hxi,sc.id);events.push({clubId:f.home,scorerId:sc.id,assistId:a?.id||null})}for(let i=0;i<ag;i++){const sc=weightedScorerGeneric(f.away,axi),a=weightedAssistGeneric(f.away,axi,sc.id);events.push({clubId:f.away,scorerId:sc.id,assistId:a?.id||null})}const hr=hg>ag?'win':hg<ag?'loss':'draw',ar=hg>ag?'loss':hg<ag?'win':'draw';updatePlayerMatchStats(f.home,f.compId,hxi,hr,hg,ag,events);updatePlayerMatchStats(f.away,f.compId,axi,ar,ag,hg,events)}
function genericStrength(cid){const xi=autoLineup(cid).xi;return xi.reduce((s,x)=>s+player(x.playerId).ovr*posFit(player(x.playerId),x.slotPos),0)/11}
function poisson(lambda){let L=Math.exp(-lambda),k=0,p=1;do{k++;p*=Math.random()}while(p>L&&k<9);return k-1}
function weightedScorerGeneric(cid,ids){const ps=ids.map(player),arr=[];ps.forEach(p=>{const w=Math.max(1,p.attrs.fin-45)+(p.pos==='ATA'?25:['PE','PD','MAT'].includes(p.pos)?12:0);for(let i=0;i<Math.max(1,Math.round(w/8));i++)arr.push(p)});return pick(arr)||ps[0]}
function weightedAssistGeneric(cid,ids,sc){const ps=ids.map(player).filter(p=>p.id!==sc).sort((a,b)=>(b.attrs.pas+b.attrs.dri)-(a.attrs.pas+a.attrs.dri));return Math.random()<.8?pick(ps.slice(0,5)):null}
function simulateUntil(date,skipFixtureId){state.fixtures.filter(f=>!f.played&&f.id!==skipFixtureId&&f.date<=date&&f.home!==state.clubId&&f.away!==state.clubId).sort((a,b)=>a.date.localeCompare(b.date)).forEach(simulateFixture);maybeAdvanceCup();checkCompetitionFinish()}
function checkCompetitionFinish(){Object.values(state.competitions).forEach(c=>{if(c.type==='league'){const fs=state.fixtures.filter(f=>f.compId===c.id);if(fs.length&&fs.every(f=>f.played)){c.finished=true;c.champion=sortedTable(c.id)[0]?.clubId}}})}

function transferWindowOpen(){if(state.offseason?.active)return true;const month=+state.date.slice(5,7);return month===1||month===7}
function renderTransfers(){const market=state.db.players.filter(p=>p.clubId!==state.clubId&&!club(p.clubId).guest).sort((a,b)=>b.ovr-a.ovr).slice(0,80),open=transferWindowOpen(),offers=state.incomingOffers||[];$('#transfers').innerHTML=`<div class="page-head"><div><h1>Transferências</h1><p>${open?'Janela aberta':'Janela fechada — pré-contratos continuam possíveis para vínculos no fim.'}</p></div><span class="tag">${state.offseason?.active?`Pós-temporada até ${fmtDate(state.offseason.endDate)}`:open?'JANELA ABERTA':'JANELA FECHADA'}</span></div><div class="grid grid-3"><div class="card"><div class="metric">${brl(state.budget)}</div><div class="metric-label">Caixa para transferências</div></div><div class="card"><div class="metric">${state.precontracts.length}</div><div class="metric-label">Pré-contratos acertados</div></div><div class="card"><div class="metric">${state.loans.filter(x=>x.active).length}</div><div class="metric-label">Empréstimos ativos</div></div></div>${offers.length?`<div class="card" style="margin-top:13px"><h3>Propostas recebidas</h3>${offers.map(o=>{const pp=player(o.playerId);return `<div class="market-card"><div class="grow"><b>${club(o.fromClubId).name} → ${pp?.name||'Jogador'}</b><div class="tiny muted">${o.type==='loan'?'Empréstimo':'Transferência definitiva'} • ${brl(o.value)}</div></div><button class="success" onclick="acceptIncoming('${o.id}')">Aceitar</button><button onclick="rejectIncoming('${o.id}')">Recusar</button></div>`}).join('')}</div>`:''}<div class="card" style="margin-top:13px"><h3>Mercado</h3><div class="field"><input id="marketSearch" placeholder="Buscar jogador ou clube..."></div><div id="marketList">${marketHtml(market,open)}</div></div>`;$('#marketSearch').oninput=e=>{const q=e.target.value.toLowerCase();$('#marketList').innerHTML=marketHtml(market.filter(p=>p.name.toLowerCase().includes(q)||club(p.clubId).name.toLowerCase().includes(q)),open)}}
function marketHtml(ps,open){return ps.slice(0,60).map(p=>`<div class="market-card"><span class="pos">${p.pos}</span><div class="grow"><b>${p.name}</b><div class="tiny muted">${club(p.clubId).name} • ${p.age}a • OVR ${p.ovr} • ${brl(p.value)} • contrato ${p.contract}a</div></div><div class="market-actions"><button ${open?'':'disabled'} onclick="offerBuy('${p.id}')">Comprar</button><button ${open?'':'disabled'} onclick="offerLoan('${p.id}')">Empréstimo</button><button ${p.contract<=1?'':'disabled'} onclick="preContract('${p.id}')">Pré-contrato</button></div></div>`).join('')}
window.offerBuy=pid=>{const p=player(pid),ask=Math.round(p.value*(p.unhappy?.75:1)*(p.contract<=1?.82:1));modal(`<div class="modal-head"><div><h2>Negociação — ${p.name}</h2><div class="tiny muted">${club(p.clubId).name} • OVR ${p.ovr}</div></div><button onclick="closeModal()">✕</button></div><div class="negotiation"><div class="field"><label>Oferta</label><input type="number" id="offerValue" value="${ask}" step="100000"></div><div class="field"><label>Salário mensal</label><input type="number" id="offerWage" value="${Math.round(p.wage*1.12)}" step="5000"></div><div class="tension" style="--t:${clamp(Math.round((ask/(p.value*1.25))*70),15,78)}%"></div><div class="tiny muted">A tensão aumenta com ofertas muito abaixo do valor esperado.</div><button class="primary" onclick="submitBuy('${pid}',${ask})">Enviar proposta</button></div>`,true)};
window.submitBuy=(pid,ask)=>{const p=player(pid),value=+$('#offerValue').value,wage=+$('#offerWage').value;if(value>state.budget)return toast('Orçamento insuficiente.');const ratio=value/ask,chance=clamp(.18+ratio*.62+(p.unhappy?.12:0)+(p.contract<=1?.08:0)-(state.opts.realistic?.08:0),.04,.93);if(Math.random()<chance){const old=club(p.clubId).name;state.budget-=value;p.clubId=state.clubId;p.wage=wage;p.contract=3;p.morale=82;p.unhappy=false;state.transactions.push({date:state.date,type:'Compra',player:p.name,value});state.lineup=autoLineup(state.clubId,state.formation);state.wageSpent=teamPlayers(state.clubId).reduce((s,x)=>s+x.wage,0);state.news.push({date:state.date,title:'Contratação concluída',body:`${p.name} chega do ${old} por ${brl(value)}.`});closeModal();save();renderTransfers();renderTop();toast('Transferência concluída.')}else{toast('A proposta foi recusada. Tente melhorar os termos.')}};
window.offerLoan=pid=>{const p=player(pid);const fee=Math.round(p.value*.035);if(fee>state.budget)return toast('Orçamento insuficiente para a taxa.');const chance=clamp(.64-(p.ovr-club(state.clubId).rep)/100+(p.status==='Reserva'?.12:0),.15,.9);if(Math.random()>chance)return toast('O clube/jogador recusou o empréstimo.');const from=p.clubId;state.budget-=fee;p.loanFrom=from;p.clubId=state.clubId;state.loans.push({playerId:p.id,from,to:state.clubId,active:true,returnSeason:state.seasonStartYear+1});state.lineup=autoLineup(state.clubId,state.formation);state.transactions.push({date:state.date,type:'Empréstimo',player:p.name,value:fee});save();renderTransfers();toast(`${p.name} chega por empréstimo.`)};
window.preContract=pid=>{const p=player(pid);if(p.contract>1)return toast('Só é possível pré-contrato com vínculo próximo do fim.');if(state.precontracts.some(x=>x.playerId===pid))return toast('Pré-contrato já acertado.');const bonus=Math.round(p.wage*6);if(bonus>state.budget)return toast('Sem caixa para luvas.');state.budget-=bonus;state.precontracts.push({playerId:pid,to:state.clubId,executeSeason:state.seasonStartYear+1});state.news.push({date:state.date,title:'Pré-contrato assinado',body:`${p.name} chegará no início da próxima temporada.`});save();renderTransfers();renderTop();toast('Pré-contrato acertado.')};

function renderScouts(){const targets=state.db.players.filter(p=>p.clubId!==state.clubId&&!club(p.clubId).guest).sort(()=>Math.random()-.5).slice(0,10);$('#scouts').innerHTML=`<div class="page-head"><div><h1>Olheiros</h1><p>Equipe de observação sem pay-to-win: contrate e melhore sua rede com o dinheiro do clube.</p></div><button onclick="hireScout()">Contratar olheiro</button></div><div class="grid grid-2">${state.scouts.map(s=>`<div class="card"><h3>${s.name}</h3><div class="small">Nível ${s.level} • ${s.region}</div><div class="tiny muted">Precisão ${s.accuracy}%</div><div class="progress" style="margin-top:9px"><span style="width:${s.accuracy}%"></span></div></div>`).join('')}</div><div class="card" style="margin-top:13px"><h3>Relatórios rápidos</h3>${targets.map(p=>`<div class="market-card"><span class="pos">${p.pos}</span><div class="grow"><b>${p.name}</b><div class="tiny muted">${club(p.clubId).name} • OVR estimado ${clamp(p.ovr+rnd(-3,3),50,92)} • ${p.traits[0]}</div></div></div>`).join('')}</div>`}
window.hireScout=()=>{const cost=2_500_000;if(state.budget<cost)return toast('Você precisa de R$ 2,5 mi.');state.budget-=cost;state.scouts.push({id:uid(),name:`Olheiro ${state.scouts.length+1}`,level:1+rnd(0,2),region:pick(['Brasil','América do Sul','Europa']),accuracy:rnd(57,75)});save();renderScouts();renderTop();toast('Novo olheiro contratado.')};

function renderCalendar(){const d=new Date(state.date+'T12:00:00'),year=d.getFullYear(),month=d.getMonth(),first=new Date(year,month,1),last=new Date(year,month+1,0),start=first.getDay(),cells=[];for(let i=0;i<start;i++)cells.push('');for(let day=1;day<=last.getDate();day++){const ds=new Date(year,month,day,12).toISOString().slice(0,10),fs=state.fixtures.filter(f=>f.date===ds&&(f.home===state.clubId||f.away===state.clubId));cells.push(`<div class="day ${ds===state.date?'today':''}"><div class="num">${day}</div>${fs.map(f=>`<div class="event">${comp(f.compId).name}<br><b>${club(f.home).abbr} x ${club(f.away).abbr}</b></div>`).join('')}${state.offseason?.active&&ds===state.offseason.endDate?'<div class="event">Fim da janela pós-temporada</div>':''}</div>`)}$('#calendar').innerHTML=`<div class="page-head"><div><h1>Calendário</h1><p>${first.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</p></div><button onclick="advanceToNextEvent()">Avançar</button></div><div class="card"><div class="calendar">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=>`<div class="tiny muted" style="text-align:center">${x}</div>`).join('')}${cells.map(x=>x||'<div></div>').join('')}</div></div>`}
function renderFinances(){const spent=state.transactions.filter(t=>['Compra','Empréstimo'].includes(t.type)).reduce((s,t)=>s+(t.value||0),0),sales=state.transactions.filter(t=>t.type==='Venda').reduce((s,t)=>s+(t.value||0),0);$('#finances').innerHTML=`<div class="page-head"><div><h1>Finanças</h1><p>Movimentação da temporada ${state.season}</p></div></div><div class="grid grid-4"><div class="card"><div class="metric">${brl(state.budget)}</div><div class="metric-label">Caixa de transferências</div></div><div class="card"><div class="metric">${brl(spent)}</div><div class="metric-label">Gasto em contratações</div></div><div class="card"><div class="metric">${brl(sales)}</div><div class="metric-label">Receita de vendas</div></div><div class="card"><div class="metric">${brl(state.wageSpent)}</div><div class="metric-label">Folha mensal</div></div></div><div class="card" style="margin-top:13px"><h3>Histórico</h3>${state.transactions.slice().reverse().map(t=>`<div class="fixture"><span class="tag">${t.type}</span><div class="teams"><b>${t.player}</b><div class="tiny muted">${fmtDate(t.date)}</div></div><b>${brl(t.value||0)}</b></div>`).join('')||'<p class="muted">Ainda sem movimentações.</p>'}</div>`}
function renderJobs(){const me=state.manager.rating,open=state.db.clubs.filter(c=>!c.guest&&c.id!==state.clubId).map(c=>({c,min:clamp(4.5+(c.rep-60)/9,4.5,9.4),confidence:rnd(25,70)})).filter(x=>x.confidence<46&&x.min<=me+.9).sort((a,b)=>b.c.rep-a.c.rep).slice(0,9);$('#jobs').innerHTML=`<div class="page-head"><div><h1>Vagas de técnico</h1><p>Sua nota: ${me.toFixed(2)}. Candidaturas dependem da reputação e do desempenho recente.</p></div></div><div class="card">${open.map(x=>`<div class="market-card"><div class="club-badge" style="background:linear-gradient(135deg,${x.c.color},${x.c.color2});width:34px;height:34px">${x.c.abbr}</div><div class="grow"><b>${x.c.name}</b><div class="tiny muted">Confiança no treinador atual: ${x.confidence}% • perfil sugerido ${x.min.toFixed(1)}+</div></div><button ${state.applications.includes(x.c.id)?'disabled':''} onclick="applyJob('${x.c.id}',${x.min})">${state.applications.includes(x.c.id)?'Candidatado':'Candidatar-se'}</button></div>`).join('')||'<p class="muted">Nenhuma vaga compatível agora.</p>'}</div>`}
window.applyJob=(cid,min)=>{state.applications.push(cid);const c=club(cid),chance=clamp(.18+(state.manager.rating-min)*.24+(state.manager.wins-state.manager.losses)*.008,.04,.78);if(Math.random()<chance){state.news.push({date:state.date,title:'Entrevista de emprego',body:`${c.name} demonstrou interesse no seu trabalho.`});toast(`${c.name} quer conversar.`)}else toast(`${c.name} recusou a candidatura.`);save();renderJobs()};

function advanceToNextEvent(){
 if(state.match&&!state.match.finished)return toast('Termine ou pause a partida antes de avançar.');
 if(state.offseason?.active){const next=addDays(state.date,7),target=next>state.offseason.endDate?state.offseason.endDate:next;state.date=target;randomMarketEvent();if(state.date>=state.offseason.endDate){startNextSeason();toast('Nova temporada iniciada!')}save();renderAll();return}
 const n=nextUserFixture();if(!n){checkSeasonEnd();if(!state.offseason?.active)return toast('Não há próximo evento.');return}simulateUntil(n.date,n.id);state.date=n.date;recoverSquad();randomEvent();save();renderAll();showPage('dashboard');toast(`Avançado para ${fmtDate(state.date)}.`)
}
window.advanceToNextEvent=advanceToNextEvent;
function recoverSquad(){teamPlayers(state.clubId).forEach(p=>{p.fitness=clamp(p.fitness+rnd(3,7),40,100);if(Math.random()<.05)p.morale=clamp(p.morale+rnd(-2,3),30,100)})}
function randomEvent(){if(Math.random()>.23)return;const ps=teamPlayers(state.clubId),p=pick(ps),events=[()=>{p.fitness=clamp(p.fitness-rnd(8,18),35,100);return `${p.name} sofreu um problema físico leve fora de jogo e perdeu condição.`},()=>{p.morale=clamp(p.morale+8,20,100);return `${p.name} recebeu elogios da torcida e ganhou moral.`},()=>{p.unhappy=true;p.morale=clamp(p.morale-10,20,100);return `${p.name} está insatisfeito com o espaço no elenco e pode ouvir propostas.`}];const body=pick(events)();state.news.push({date:state.date,title:'Evento de elenco',body})}
function randomMarketEvent(){if(Math.random()>.42)return;const p=pick(teamPlayers(state.clubId).filter(x=>!x.generated));if(!p)return;const bidder=pick(state.db.clubs.filter(c=>!c.guest&&c.id!==state.clubId)),isLoan=Math.random()<.28,value=Math.round(p.value*(isLoan?.04:(.8+Math.random()*.45))),offer={id:uid(),playerId:p.id,fromClubId:bidder.id,type:isLoan?'loan':'sale',value};state.incomingOffers=state.incomingOffers||[];state.incomingOffers.push(offer);state.news.push({date:state.date,title:'Proposta recebida',body:`${bidder.name} enviou uma proposta por ${p.name}: ${isLoan?'empréstimo por ':''}${brl(value)}.`})}
window.acceptIncoming=id=>{state.incomingOffers=state.incomingOffers||[];const o=state.incomingOffers.find(x=>x.id===id);if(!o)return;const p=player(o.playerId);if(!p)return;if(o.type==='sale'){state.budget+=o.value;p.clubId=o.fromClubId;state.transactions.push({date:state.date,type:'Venda',player:p.name,value:o.value});state.news.push({date:state.date,title:'Venda concluída',body:`${p.name} foi negociado com ${club(o.fromClubId).name} por ${brl(o.value)}.`})}else{const from=state.clubId;p.loanFrom=from;p.clubId=o.fromClubId;state.budget+=o.value;state.loans.push({playerId:p.id,from,to:o.fromClubId,active:true,returnSeason:state.seasonStartYear+1});state.transactions.push({date:state.date,type:'Empréstimo cedido',player:p.name,value:o.value})}state.incomingOffers=state.incomingOffers.filter(x=>x.id!==id);state.lineup=autoLineup(state.clubId,state.formation);state.wageSpent=teamPlayers(state.clubId).reduce((s,x)=>s+x.wage,0);save();renderTransfers();renderTop();toast('Proposta aceita.')};
window.rejectIncoming=id=>{state.incomingOffers=(state.incomingOffers||[]).filter(x=>x.id!==id);save();renderTransfers();toast('Proposta recusada.')};

function checkSeasonEnd(){
 if(state.seasonEnded||state.offseason?.active)return;const leagues=['brA','brB'];const done=leagues.every(id=>state.fixtures.filter(f=>f.compId===id).every(f=>f.played));if(!done)return;finishSeason()
}
function finishSeason(){
 checkCompetitionFinish();state.seasonEnded=true;const ta=sortedTable('brA'),tb=sortedTable('brB'),userCompId=club(state.clubId).division==='A'?'brA':'brB',champ=ta[0]?.clubId,relegated=ta.slice(-4).map(x=>x.clubId),promoted=tb.slice(0,4).map(x=>x.clubId);const topSc=compLeaders('brA','goals')[0]||compLeaders('brB','goals')[0],mvp=compLeaders('brA','rating')[0]||compLeaders('brB','rating')[0];state.seasonSummary={season:state.season,userCompId,champion:champ,relegated,promoted,topScorer:topSc?{name:topSc.p.name,goals:topSc.s.goals,clubId:topSc.p.clubId}:null,mvp:mvp?{name:mvp.p.name,rating:(mvp.s.ratingSum/mvp.s.ratingApps),clubId:mvp.p.clubId}:null};
 state.qualifications={};ta.slice(0,4).forEach(r=>state.qualifications[r.clubId]='libertadores');ta.slice(4,8).forEach(r=>state.qualifications[r.clubId]='sudamericana');relegated.forEach(id=>club(id).division='B');promoted.forEach(id=>club(id).division='A');if(champ===state.clubId){state.manager.titles++;state.manager.rating=clamp(state.manager.rating+.35,1,10)}state.offseason={active:true,endDate:addDays(state.date,30),summarySeen:false};state.news.push({date:state.date,title:`Fim da temporada ${state.season}`,body:`${club(champ).name} foi campeão brasileiro. A janela pós-temporada ficará aberta por 30 dias.`});showSeasonSummary();save();renderTop()
}
function showSeasonSummary(){const s=state.seasonSummary;if(!s)return;const div=s.userCompId||'brA';modal(`<div class="modal-head"><div><h2>🏁 Fim da temporada ${s.season}</h2><div class="tiny muted">A janela de transferências pós-temporada está aberta por 30 dias.</div></div><button onclick="closeSeasonSummary()">✕</button></div><div class="season-summary"><div class="summary-hero"><div class="metric" style="font-size:24px">🏆 ${club(s.champion).name}</div><div class="metric-label">Campeão do Liga Nacional Série A</div></div><div class="grid grid-2"><div class="card"><h3>Artilheiro</h3>${s.topScorer?`<b>${s.topScorer.name}</b><div class="tiny muted">${club(s.topScorer.clubId).name} • ${s.topScorer.goals} gols</div>`:'—'}</div><div class="card"><h3>MVP</h3>${s.mvp?`<b>${s.mvp.name}</b><div class="tiny muted">${club(s.mvp.clubId).name} • nota ${s.mvp.rating.toFixed(2)}</div>`:'—'}</div></div><div class="grid grid-2"><div class="card"><h3>Rebaixados</h3>${s.relegated.map(id=>`<div>${club(id).name}</div>`).join('')}</div><div class="card"><h3>Promovidos</h3>${s.promoted.map(id=>`<div>${club(id).name}</div>`).join('')}</div></div><div class="card"><h3>Tabela final da sua divisão</h3>${tableHtml(div)}</div></div>`) }
