function startNextSeasonBaseV02(){
 const prev=state.season;state.history.push({type:'season',season:prev,summary:state.seasonSummary});state.seasonStartYear++;state.season=`${state.seasonStartYear}/${String(state.seasonStartYear+1).slice(-2)}`;state.date=`${state.seasonStartYear}-01-05`;state.manager.seasonDelta=0;state.seasonSummary=null;state.offseason=null;state.applications=[];state.incomingOffers=[];
 state.loans.filter(l=>l.active&&l.returnSeason<=state.seasonStartYear).forEach(l=>{const p=player(l.playerId);if(p){p.clubId=l.from;p.loanFrom=null}l.active=false});state.precontracts.filter(x=>x.executeSeason<=state.seasonStartYear).forEach(x=>{const p=player(x.playerId);if(p){p.clubId=x.to;p.contract=x.contract||3;p.wage=x.wage||p.wage;p.morale=82}});state.precontracts=state.precontracts.filter(x=>x.executeSeason>state.seasonStartYear);
 state.db.players.forEach(p=>{p.age++;p.contract=Math.max(0,p.contract-1);if(p.age<=23&&p.ovr<p.pot)p.ovr=clamp(p.ovr+rnd(0,2),45,p.pot);else if(p.age>=31&&Math.random()<.55)p.ovr=clamp(p.ovr-rnd(0,2),45,94);p.fitness=96;p.morale=clamp(p.morale+rnd(-2,3),45,95);resetPlayerSeason(p)});state.lineup=autoLineup(state.clubId,state.formation);state.wageSpent=teamPlayers(state.clubId).reduce((s,p)=>s+p.wage,0);state.budget+=Math.round(club(state.clubId).budget*.35);createSeasonStructure(state);state.news.push({date:state.date,title:`Temporada ${state.season}`,body:'Calendário atualizado, promovidos e rebaixados reposicionados e competições renovadas.'});save()
}

