/* ======================== SOCCER MANAGER V0.3 PATCH ======================== */
const V03_POSITIONS=['GOL','ZAG','LD','LE','VOL','MC','MLE','MLD','MAT','SA','PE','PD','ATA'];
const POS_ZONE={GOL:'gk',ZAG:'def',LD:'flank',LE:'flank',VOL:'mid',MC:'mid',MLE:'flank',MLD:'flank',MAT:'mid',SA:'att',PE:'att',PD:'att',ATA:'att'};
const ADJ={def:['flank','mid'],flank:['def','mid','att'],mid:['def','flank','att'],att:['flank','mid']};
function adaptationScore(p,slot){
 if(!p)return -99;if(slot==='GOL')return p.pos==='GOL'?1:-99;if(p.pos==='GOL')return -99;
 if(p.pos===slot)return 1;if((p.positions||[]).includes(slot))return 0;
 const z1=POS_ZONE[p.pos],z2=POS_ZONE[slot];let pen=z1===z2?-1:ADJ[z1]?.includes(z2)?-3:-5;
 const a=p.attrs||{};
 if(['LD','LE','MLE','MLD','PE','PD'].includes(slot)&&a.vel>=75)pen+=1;
 if(['VOL','ZAG'].includes(slot)&&a.def>=74)pen+=1;
 if(['MAT','SA','ATA'].includes(slot)&&a.fin>=74)pen+=1;
 if(['MC','MAT','VOL'].includes(slot)&&a.pas>=74)pen+=1;
 return clamp(pen,-5,0)
}
function canPlay(p,slot){return adaptationScore(p,slot)>-90}
function effectiveOvr(p,slot){return clamp(p.ovr+adaptationScore(p,slot),40,99)}
function posFit(p,slot){const e=effectiveOvr(p,slot);return e/Math.max(1,p.ovr)}
function energyHtml(p){const v=clamp(Math.round(p.fitness),0,100),c=v<45?'var(--danger)':v<70?'var(--warn)':'var(--accent2)';return `<div class="energy-wrap"><div class="energy-bar"><span style="width:${v}%;background:${c}"></span></div><b>${v}%</b></div>`}

// Corrige idades conhecidas usadas no banco de 2026.
const AGE_FIXES={"Naimer":34,"Arascaete":32,"Brone Bidun":21,"Cauli":31};
function applyAgeFixes(){if(!state?.db?.players||state.seasonStartYear!==2026)return;state.db.players.forEach(p=>{if(AGE_FIXES[p.name]!==undefined)p.age=AGE_FIXES[p.name]})}

function tacticOptions(){const presets=Object.keys(FORMS).map(f=>({key:f,label:f,slots:FORMS[f]}));return presets.concat((state.customTactics||[]).map(t=>({key:'custom:'+t.id,label:'★ '+t.name,slots:t.slots}))) }
function getTacticSlots(key){if(key?.startsWith('custom:'))return state.customTactics.find(t=>'custom:'+t.id===key)?.slots||FORMS['4-2-3-1'];return FORMS[key]||FORMS['4-2-3-1']}
function autoLineup(cid,formation='4-2-3-1',poolOverride=null){const slots=getTacticSlots(formation),pool=(poolOverride||teamPlayers(cid)).slice(),used=new Set(),xi=[];slots.forEach(s=>{let candidates=pool.filter(p=>!used.has(p.id)&&canPlay(p,s.p)).sort((a,b)=>(effectiveOvr(b,s.p)+b.form/25+b.morale/70)-(effectiveOvr(a,s.p)+a.form/25+a.morale/70));let p=candidates[0]||pool.filter(x=>!used.has(x.id)).sort((a,b)=>b.ovr-a.ovr)[0];if(p){used.add(p.id);xi.push({slotPos:s.p,x:s.x,y:s.y,playerId:p.id})}});const rest=pool.filter(p=>!used.has(p.id)).sort((a,b)=>b.ovr-a.ovr);return{formation,xi,bench:rest.slice(0,9).map(p=>p.id),out:rest.slice(9).map(p=>p.id)}}

function renderSquad(){applyAgeFixes();const ps=teamPlayers(state.clubId).slice().sort((a,b)=>b.ovr-a.ovr);let sel=player(state.selectedPlayer)||ps[0];state.selectedPlayer=sel?.id;$('#squad').innerHTML=`<div class="page-head"><div><h1>Elenco</h1><p>${ps.length} jogadores • energia, moral e evolução dinâmica</p></div><span class="tag">${state.season}</span></div><div class="split"><div class="card" style="padding:0"><div class="table-wrap" style="border:0"><table class="table"><thead><tr><th>Pos</th><th>Jogador</th><th>Posições</th><th>Idade</th><th>OVR</th><th>POT</th><th>Energia</th><th>Moral</th><th>Contrato</th></tr></thead><tbody>${ps.map(p=>`<tr class="clickable" onclick="selectPlayer('${p.id}','squad')"><td><span class="pos">${p.pos}</span></td><td><b>${p.name}</b>${p.generated?'<div class="tiny muted">Gerado / base</div>':''}</td><td>${p.positions.join(' / ')}</td><td>${p.age}</td><td class="rating ${ratingClass(p.ovr)}">${p.ovr}</td><td>${p.pot}</td><td>${energyHtml(p)}</td><td>${p.morale}%</td><td>${p.contract}a</td></tr>`).join('')}</tbody></table></div></div><div class="card player-panel" id="playerPanel">${playerDetail(sel)}</div></div>`}

function renderTactics(){
 if(!state.lineup||state.lineup.formation!==state.formation)state.lineup=autoLineup(state.clubId,state.formation);const sel=player(state.selectedPlayer)||player(state.lineup.xi[0]?.playerId);state.selectedPlayer=sel?.id;const target=state.tacticTarget,opts=tacticOptions();
 $('#tactics').innerHTML=`<div class="page-head"><div><h1>Táticas</h1><p>Jogadores podem atuar fora da posição natural com perda de OVR. Apenas goleiros podem jogar no gol.</p></div><div style="display:flex;gap:7px"><button onclick="openCustomTactic()">+ Criar tática</button><select id="formationSelect" style="width:190px">${opts.map(f=>`<option value="${f.key}" ${f.key===state.formation?'selected':''}>${f.label}</option>`).join('')}</select></div></div><div class="grid" style="grid-template-columns:minmax(0,1.1fr) minmax(330px,.9fr)"><div class="card"><div class="pitch"><div class="center-circle"></div>${state.lineup.xi.map((s,i)=>{const p=player(s.playerId),eff=effectiveOvr(p,s.slotPos);return `<div class="slot ${target===i?'target':''}" style="left:${s.x}%;top:${s.y}%"><button onclick="targetSlot(${i});selectPlayer('${p.id}','tactics')"><div class="slot-bubble">${s.slotPos}</div><small>${p.name} • ${eff}${eff!==p.ovr?` (${eff-p.ovr>0?'+':''}${eff-p.ovr})`:''}</small></button></div>`}).join('')}</div><div class="grid grid-3" style="margin-top:10px"><div><label class="tiny muted">Pressão</label><input type="range" min="20" max="90" value="${state.pressing}" id="pressing"></div><div><label class="tiny muted">Linha defensiva</label><input type="range" min="20" max="90" value="${state.line}" id="line"></div><div><label class="tiny muted">Ritmo</label><input type="range" min="20" max="90" value="${state.tempo}" id="tempo"></div></div><div class="field" style="margin-top:10px"><label>Mentalidade</label><select id="mentalitySelect">${['Ultradefensivo','Defensivo','Equilibrado','Ofensivo','Ultraofensivo'].map(x=>`<option ${x===state.mentality?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="grid"><div class="card"><h3>Reservas ${target!==null?`• slot ${state.lineup.xi[target].slotPos}`:''}</h3><div class="bench-grid">${state.lineup.bench.map(id=>tacticChipV03(id,'bench',target)).join('')}</div><h3 style="margin-top:14px">Não relacionados</h3><div class="bench-grid">${state.lineup.out.map(id=>tacticChipV03(id,'out',target)).join('')}</div></div><div class="card player-panel" style="position:static">${playerDetail(sel)}</div></div></div>`;
 $('#formationSelect').onchange=e=>{state.formation=e.target.value;state.lineup=autoLineup(state.clubId,state.formation);state.tacticTarget=null;save();renderTactics()};$('#mentalitySelect').onchange=e=>{state.mentality=e.target.value;save()};['pressing','line','tempo'].forEach(id=>{$('#'+id).onchange=e=>{state[id]=+e.target.value;save()}})
}
function tacticChipV03(id,area,target){const p=player(id),slot=target!==null?state.lineup.xi[target].slotPos:null,eff=slot?effectiveOvr(p,slot):p.ovr;return `<div class="player-chip" onclick="selectPlayer('${p.id}','tactics')"><span class="pos">${p.pos}</span><div class="grow"><b>${p.name}</b><span class="tiny muted">OVR ${p.ovr}${slot?` → ${eff} em ${slot}`:''} • ${p.positions.join('/')}</span></div>${target!==null?`<button onclick="event.stopPropagation();placeInSlot('${p.id}',${target},'${area}')">Escalar</button>`:`<button onclick="event.stopPropagation();moveBenchStatus('${p.id}','${area}')">${area==='bench'?'Não relacionar':'Banco'}</button>`}</div>`}
window.moveBenchStatus=(pid,from)=>{const a=state.lineup[from],to=from==='bench'?'out':'bench',b=state.lineup[to],i=a.indexOf(pid);if(i<0)return;a.splice(i,1);b.push(pid);save();renderTactics()};
window.placeInSlot=(pid,idx,area)=>{const slot=state.lineup.xi[idx],p=player(pid);if(!canPlay(p,slot.slotPos))return toast('Somente goleiros podem atuar no gol.');const old=slot.playerId;slot.playerId=pid;const arr=state.lineup[area],i=arr.indexOf(pid);if(i>=0)arr[i]=old;else state.lineup.bench.push(old);state.selectedPlayer=pid;state.tacticTarget=null;save();renderTactics();toast(`${p.name} escalado em ${slot.slotPos} com OVR efetivo ${effectiveOvr(p,slot.slotPos)}.`)};
window.openCustomTactic=()=>{const base=getTacticSlots(state.formation).map(s=>({...s}));modal(`<div class="modal-head"><div><h2>🧠 Criar tática personalizada</h2><div class="tiny muted">Edite função e posição de cada um dos 11 espaços e salve para usar quando quiser.</div></div><button onclick="closeModal()">✕</button></div><div class="field"><label>Nome</label><input id="customName" value="Minha tática ${state.customTactics.length+1}"></div><div class="field"><label>Mentalidade padrão</label><select id="customMentality">${['Ultradefensivo','Defensivo','Equilibrado','Ofensivo','Ultraofensivo'].map(x=>`<option>${x}</option>`).join('')}</select></div><div id="slotEditors">${base.map((s,i)=>`<div class="slot-editor"><select id="cp${i}">${V03_POSITIONS.map(p=>`<option ${p===s.p?'selected':''}>${p}</option>`).join('')}</select><label class="tiny">X <input type="range" min="8" max="92" id="cx${i}" value="${s.x}"></label><label class="tiny">Y <input type="range" min="8" max="92" id="cy${i}" value="${s.y}"></label></div>`).join('')}</div><button class="primary" onclick="saveCustomTactic()">Salvar tática</button>`)};
window.saveCustomTactic=()=>{const slots=[];for(let i=0;i<11;i++)slots.push({p:$('#cp'+i).value,x:+$('#cx'+i).value,y:+$('#cy'+i).value});if(slots.filter(x=>x.p==='GOL').length!==1)return toast('A tática precisa ter exatamente 1 goleiro.');const t={id:uid(),name:$('#customName').value.trim()||'Tática personalizada',mentality:$('#customMentality').value,slots};state.customTactics.push(t);state.formation='custom:'+t.id;state.mentality=t.mentality;state.lineup=autoLineup(state.clubId,state.formation);save();closeModal();renderTactics();toast('Tática personalizada salva.')};

function fatigueHtml(m){if(!m)return '<p class="muted tiny">A energia começa em 100% e diminui durante a partida.</p>';return m.userXI.map(s=>{const p=player(s.playerId),fat=Math.round(m.fatigue[p.id]||0),energy=clamp(100-fat,0,100),c=energy<40?'var(--danger)':energy<65?'var(--warn)':'var(--accent2)';return `<div class="fatigue-line"><span><b>${p.name}</b> <span class="tiny muted">${s.slotPos}</span></span><div class="energy-wrap" style="width:150px"><div class="energy-bar"><span style="width:${energy}%;background:${c}"></span></div><b>${energy}%</b></div></div>`}).join('')}

function renderMatch(){const f=nextUserFixture();if(!f){$('#match').innerHTML=`<div class="page-head"><div><h1>Partida</h1><p>Sem jogo pendente.</p></div></div><div class="card">${state.offseason?.active?'A temporada terminou. Use o período de transferências antes da próxima temporada.':'Não há partida agendada.'}</div>`;return}const h=club(f.home),a=club(f.away),m=state.match&&state.match.fixtureId===f.id?state.match:null,c=comp(f.compId);$('#match').innerHTML=`<div class="page-head"><div><h1>${c.name}</h1><p>${fmtDate(f.date)}${f.round?` • ${f.round}`:''} • ${m?.userFormation||state.formation}</p></div><div style="display:flex;gap:7px"><button onclick="openCompetition('${f.compId}')">Ver competição</button>${m&&!m.finished?'<span class="tag">● AO VIVO</span>':''}</div></div><div class="card scoreboard"><div class="team-score"><div class="name club-link" onclick="openClub('${h.id}')">${h.name}</div><div class="score" id="homeScore">${m?m.home:0}</div></div><div class="clock" id="matchClock">${m?m.minute:0}'</div><div class="team-score"><div class="name club-link" onclick="openClub('${a.id}')">${a.name}</div><div class="score" id="awayScore">${m?m.away:0}</div></div></div><div class="match-layout"><div class="card"><div class="match-pitch" id="matchPitch"><div class="midline"></div><div class="circle"></div>${pitchDots()}<div class="ball" id="ball" style="left:50%;top:50%"></div></div><div class="match-controls" style="margin-top:10px">${['Ultradefensivo','Defensivo','Equilibrado','Ofensivo','Ultraofensivo'].map(x=>`<button onclick="setLiveMentality('${x}')">${x}</button>`).join('')}<button onclick="openSubs(false)" ${!m?'disabled':''}>🔄 Substituições / Formação</button></div></div><div class="grid"><div class="card"><h3>Ações</h3><div class="match-controls"><button class="primary" onclick="startMatch()">${m&&!m.finished?'Continuar':m&&m.finished?'Encerrado':'Iniciar jogo'}</button><button onclick="speedMatch()">⏩ Rápido</button><button onclick="pauseMatch()">⏸ Pausar</button></div>${m?`<div class="tiny muted" style="margin-top:8px">Mentalidade: <b>${m.mentality}</b> • Subs ${m.subsUsed}/5</div>`:''}</div><div class="card"><h3>Estatísticas</h3><div id="matchStats">${statsHtml(m)}</div></div><div class="card"><h3>Energia restante</h3><div id="fatigueList">${fatigueHtml(m)}</div></div><div class="card"><h3>${c.type==='cup'?'Chave atual':'Classificação ao vivo'}</h3>${tableHtml(f.compId,true)}</div><div class="card"><h3>Comentários</h3><div class="commentary" id="commentary">${(m?.comments||[]).slice().reverse().map(x=>`<div class="comment"><b>${x.min}'</b> ${x.text}</div>`).join('')}</div></div></div></div>`}

function mentalityMods(m){return ({Ultradefensivo:{att:-.34,def:.26,tempo:-.25,shot:-.055},Defensivo:{att:-.15,def:.12,tempo:-.10,shot:-.025},Equilibrado:{att:0,def:0,tempo:0,shot:0},Ofensivo:{att:.15,def:-.11,tempo:.10,shot:.03},Ultraofensivo:{att:.32,def:-.25,tempo:.22,shot:.065}})[m]||{att:0,def:0,tempo:0,shot:0}}
function matchStep(){const m=state.match,f=state.fixtures.find(x=>x.id===m.fixtureId);if(!m||m.finished||m.subModal)return;m.minute++;const mm=mentalityMods(m.mentality);m.userXI.forEach(s=>{const p=player(s.playerId),inc=.34+state.pressing/280+state.tempo/360+(p.attrs.fis<70?.08:0)+(mm.tempo>0?mm.tempo*.18:0)+Math.random()*.07;m.fatigue[p.id]=clamp((m.fatigue[p.id]||0)+inc,0,100)});animatePitch();const hs=matchTeamStrength(f.home),as=matchTeamStrength(f.away),meHome=f.home===state.clubId,myMod=(state.pressing-55)/350+(state.tempo-55)/400+(state.line-50)/700;let attH=hs,attA=as;if(meHome){attH*=1+mm.att+myMod;attA*=1-mm.def}else{attA*=1+mm.att+myMod;attH*=1-mm.def}const pH=attH/(attH+attA);m.stats.posH=clamp(Math.round(45+(pH-.5)*65+rnd(-2,2)),28,72);m.stats.posA=100-m.stats.posH;const streak=state.streak||{type:null,count:0},rhythm=streak.type==='win'?Math.min(.018,streak.count*.003):streak.type==='loss'?-Math.min(.015,streak.count*.003):0;let chance=.135+(state.tempo-50)/950+mm.shot+(streak.type?rhythm:0);if(Math.random()<clamp(chance,.055,.245)){const homeAttack=Math.random()<pH,att=homeAttack?attH:attA,def=homeAttack?as:hs,quality=(att/Math.max(1,def))*Math.random(),s=m.stats;homeAttack?s.shotsH++:s.shotsA++;const xg=clamp(.025+quality*.17+Math.random()*.115,.02,.40);homeAttack?s.xgH+=xg:s.xgA+=xg;const on=Math.random()<.38+quality*.14;if(on){homeAttack?s.onH++:s.onA++;if(Math.random()<xg*(.69+Math.random()*.25)){homeAttack?m.home++:m.away++;const cid=homeAttack?f.home:f.away,sc=scorerFor(cid),asst=assistFor(cid,sc.id);m.goalEvents.push({min:m.minute,clubId:cid,scorerId:sc.id,assistId:asst?.id||null});m.comments.push({min:m.minute,text:`GOL do ${club(cid).name}! ${sc.name}${asst?` recebeu de ${asst.name}`:''} e marcou.`});toast(`⚽ ${sc.name} — ${club(cid).abbr}`)}}}if(m.minute===45&&!m.halfTimeDone){m.halfTimeDone=true;m.comments.push({min:45,text:'Intervalo. Hora de ajustar a equipe.'});save();updateMatchDom();openSubs(true);return}if(m.minute>=90){finishMatch();return}save();updateMatchDom()}

function updateStreak(result){if(result==='draw'){state.streak={type:null,count:0};return}if(state.streak?.type===result)state.streak.count++;else state.streak={type:result,count:1}}
function finishMatch(){clearInterval(matchTimer);const m=state.match;if(!m)return;const f=state.fixtures.find(x=>x.id===m.fixtureId),myHome=f.home===state.clubId;finishMatchBaseV02();const last=state.history[state.history.length-1];if(last)updateStreak(last.result);save()}

function openNegotiation(pid,type){const p=player(pid),c=club(p.clubId);if(!p||p.clubId===state.clubId)return;const rival=pick(state.db.clubs.filter(x=>!x.guest&&x.id!==state.clubId&&x.id!==p.clubId));const rivalBid=type==='pre'?Math.round(p.wage*(5+rnd(0,5))):type==='loan'?Math.round(p.value*(.02+Math.random()*.035)):Math.round(p.value*(.82+Math.random()*.35));const asking=Math.round(p.value*(p.unhappy?.78:1)*(p.contract<=1?.84:1));modal(`<div class="modal-head"><div><h2>${type==='buy'?'Compra':type==='loan'?'Empréstimo':'Pré-contrato'} — ${p.name}</h2><div class="tiny muted">${c.name} • OVR ${p.ovr} • ${p.age} anos</div></div><button onclick="closeModal()">✕</button></div><div class="grid grid-2"><div><div class="field"><label>${type==='buy'?'Oferta ao clube':type==='loan'?'Taxa de empréstimo':'Luvas'}</label><input type="number" id="negFee" value="${type==='buy'?asking:type==='loan'?Math.round(p.value*.035):Math.round(p.wage*7)}"></div><div class="field"><label>Salário mensal</label><input type="number" id="negWage" value="${Math.round(p.wage*1.15)}"></div><div class="field"><label>Bônus por assinatura</label><input type="number" id="negBonus" value="${Math.round(p.wage*3)}"></div>${type==='loan'?`<div class="field"><label>Duração</label><select id="negDuration"><option value="6">6 meses</option><option value="12" selected>1 ano</option><option value="24">2 anos</option></select></div><div class="check-row"><span>Opção de compra</span><input id="negOption" type="checkbox"></div>`:''}<button class="primary" onclick="submitNegotiation('${pid}','${type}',${rivalBid})">Enviar proposta</button></div><div class="card"><h3>Concorrência</h3><div class="market-card"><div class="club-badge" style="background:linear-gradient(135deg,${rival.color},${rival.color2});width:34px;height:34px">${rival.abbr}</div><div><b>${rival.name}</b><div class="tiny muted">Oferta estimada: ${brl(rivalBid)}</div></div></div><p class="small muted">Salário, luvas, duração e situação no clube influenciam a decisão do atleta. Pré-contrato e empréstimo também exigem negociação.</p></div></div>`)}
window.submitNegotiation=(pid,type,rivalBid)=>{const p=player(pid),fee=+$('#negFee').value,wage=+$('#negWage').value,bonus=+$('#negBonus').value,total=fee+bonus;if(total>state.budget)return toast('Orçamento insuficiente.');if(type==='pre'&&p.contract>1)return toast('O jogador ainda não pode assinar pré-contrato.');const attractiveness=(wage/Math.max(1,p.wage)-1)*.32+(bonus/Math.max(1,p.wage*4))*.15+(p.unhappy?.12:0)+(club(state.clubId).rep-club(p.clubId).rep)/180;const financial=type==='buy'?fee/Math.max(1,p.value):type==='loan'?fee/Math.max(1,p.value*.04):fee/Math.max(1,p.wage*7);let chance=clamp(.22+attractiveness+financial*.36-(rivalBid>fee?.08:0),.06,.92);if(Math.random()>chance)return toast('Negociação recusada. Melhore os termos ou tente novamente.');state.budget-=total;if(type==='buy'){const old=p.clubId;p.clubId=state.clubId;p.contract=3;p.wage=wage;p.morale=clamp(78+rnd(0,8),70,92);p.unhappy=false;state.transactions.push({date:state.date,type:'Compra',player:p.name,value:fee+bonus});state.news.push({date:state.date,title:'Transferência concluída',body:`${p.name} deixou ${club(old).name} e assinou com ${club(state.clubId).name}.`})}else if(type==='loan'){const old=p.clubId,dur=+$('#negDuration').value,option=$('#negOption').checked;p.loanFrom=old;p.clubId=state.clubId;p.wage=wage;p.morale=clamp(76+rnd(0,8),68,90);state.loans.push({playerId:p.id,from:old,to:state.clubId,active:true,returnSeason:state.seasonStartYear+(dur>12?2:1),months:dur,buyOption:option?Math.round(p.value*1.05):null});state.transactions.push({date:state.date,type:'Empréstimo',player:p.name,value:fee+bonus})}else{state.precontracts.push({playerId:p.id,to:state.clubId,executeSeason:state.seasonStartYear+1,wage,bonus});state.transactions.push({date:state.date,type:'Pré-contrato',player:p.name,value:fee+bonus})}state.lineup=autoLineup(state.clubId,state.formation);state.wageSpent=teamPlayers(state.clubId).reduce((s,x)=>s+x.wage,0);save();closeModal();renderTransfers();renderTop();toast('Acordo fechado!')};
window.offerBuy=pid=>openNegotiation(pid,'buy');window.offerLoan=pid=>openNegotiation(pid,'loan');window.preContract=pid=>openNegotiation(pid,'pre');
function marketHtml(ps,open){return ps.slice(0,150).map(p=>`<div class="market-card"><span class="pos">${p.pos}</span><div class="grow club-link" onclick="showMarketPlayer('${p.id}')"><b>${p.name}</b><div class="tiny muted">${club(p.clubId).name} • ${p.age}a • OVR ${p.ovr} • ${brl(p.value)} • ${p.contract}a</div></div><div class="market-actions"><button onclick="toggleWatch('${p.id}')">${state.watchlist.includes(p.id)?'★':'☆'}</button><button ${open?'':'disabled'} onclick="offerBuy('${p.id}')">Comprar</button><button ${open?'':'disabled'} onclick="offerLoan('${p.id}')">Empréstimo</button><button ${p.contract<=1?'':'disabled'} onclick="preContract('${p.id}')">Pré</button></div></div>`).join('')}
function renderTransfers(){const all=state.db.players.filter(p=>p.clubId!==state.clubId&&!club(p.clubId).guest).sort((a,b)=>b.ovr-a.ovr),open=transferWindowOpen(),offers=state.incomingOffers||[];$('#transfers').innerHTML=`<div class="page-head"><div><h1>Transferências</h1><p>Todos os jogadores pesquisáveis • compra, empréstimo e pré-contrato negociáveis.</p></div><span class="tag">${open?'JANELA ABERTA':'JANELA FECHADA'}</span></div><div class="tab-row"><button class="active" onclick="transferTab('market')">Mercado</button><button onclick="transferTab('watch')">Lista de observação (${state.watchlist.length})</button></div>${offers.length?`<div class="card"><h3>Propostas recebidas</h3>${offers.map(o=>{const pp=player(o.playerId);return `<div class="market-card"><div class="grow"><b>${club(o.fromClubId).name} → ${pp?.name}</b><div class="tiny muted">${o.type==='loan'?'Empréstimo':'Transferência'} • ${brl(o.value)}</div></div><button class="success" onclick="acceptIncoming('${o.id}')">Aceitar</button><button onclick="rejectIncoming('${o.id}')">Recusar</button></div>`}).join('')}</div>`:''}<div class="card" style="margin-top:13px"><div class="field"><input id="marketSearch" placeholder="Busque qualquer jogador ou clube..."></div><div id="marketList">${marketHtml(all,open)}</div></div>`;$('#marketSearch').oninput=e=>{const q=e.target.value.toLowerCase().trim();const r=all.filter(p=>p.name.toLowerCase().includes(q)||club(p.clubId).name.toLowerCase().includes(q));$('#marketList').innerHTML=marketHtml(r,open)}}
window.transferTab=t=>{if(t==='watch'){$('#marketList').innerHTML=marketHtml((state.watchlist||[]).map(player).filter(Boolean),transferWindowOpen())}else renderTransfers()};
window.toggleWatch=pid=>{state.watchlist=state.watchlist||[];state.watchlist=state.watchlist.includes(pid)?state.watchlist.filter(x=>x!==pid):[...state.watchlist,pid];save();renderTransfers()};
window.showMarketPlayer=pid=>{const p=player(pid);modal(`<div class="modal-head"><div><h2>${p.name}</h2><div class="tiny muted">${club(p.clubId).name}</div></div><button onclick="closeModal()">✕</button></div>${playerDetail(p)}`)};

function aiMarketTick(){const clubs=state.db.clubs.filter(c=>!c.guest&&c.id!==state.clubId);if(Math.random()<.38){const from=pick(clubs),targets=teamPlayers(from.id).filter(p=>p.contract<=1&&Math.random()<.7);targets.slice(0,rnd(0,2)).forEach(p=>{p.contract+=rnd(2,4);p.morale=clamp(p.morale+5,30,95)})}if(Math.random()<.30){const from=pick(clubs),to=pick(clubs.filter(c=>c.id!==from.id));const cand=pick(teamPlayers(from.id).filter(p=>!p.loanFrom&&p.age<34));if(cand&&teamPlayers(to.id).length<30){const fee=Math.round(cand.value*(.75+Math.random()*.45));cand.clubId=to.id;cand.contract=rnd(2,4);cand.morale=clamp(75+rnd(0,12),60,95);state.news.push({date:state.date,title:'Mercado se movimenta',body:`${cand.name} foi negociado de ${from.name} para ${to.name} por cerca de ${brl(fee)}.`})}}}

const SCOUT_NAMES=['André Farias','Paulo Monteiro','Rafael Teles','Leandro Braga','Gustavo Mota','Henrique Luz','Bruno Salgado','Vitor Azevedo','Eduardo Neves','Samuel Freire','Márcio Lacerda','Danilo Reis'];
function scoutCost(){return 1_500_000+state.scouts.length*1_350_000}
function renderScouts(){const sel=state.scouts.find(s=>s.id===state.selectedScout)||state.scouts[0];state.selectedScout=sel?.id;$('#scouts').innerHTML=`<div class="page-head"><div><h1>Olheiros</h1><p>Contrate, envie em viagens e mantenha uma lista de observação.</p></div><button onclick="hireScout()">Contratar próximo • ${brl(scoutCost())}</button></div><div class="grid grid-3">${state.scouts.map(s=>`<div class="card scout-card ${s.id===sel?.id?'selected':''}" onclick="selectScout('${s.id}')"><h3>${s.name}</h3><div class="small">Nível ${s.level} • Precisão ${s.accuracy}%</div><div class="tiny muted">${s.mission?`Em ${s.mission.region} até ${fmtDate(s.mission.end)}`:'Disponível para viagem'}</div></div>`).join('')}</div>${sel?`<div class="grid grid-2" style="margin-top:13px"><div class="card"><h3>Enviar ${sel.name}</h3><div class="field"><label>Região</label><select id="scoutRegion"><option>Brasil</option><option>América do Sul</option><option>Argentina e Uruguai</option><option>Europa</option></select></div><div class="field"><label>Duração</label><select id="scoutMonths"><option value="3">3 meses</option><option value="6">6 meses</option><option value="9">9 meses</option><option value="12">1 ano</option></select></div><button onclick="sendScout('${sel.id}')">Iniciar viagem</button></div><div class="card"><h3>Relatórios de ${sel.name}</h3>${(sel.reports||[]).map(id=>{const p=player(id);return p?`<div class="market-card"><span class="pos">${p.pos}</span><div class="grow club-link" onclick="showMarketPlayer('${p.id}')"><b>${p.name}</b><div class="tiny muted">${club(p.clubId).name} • OVR ${p.ovr}</div></div><button onclick="toggleWatch('${p.id}')">${state.watchlist.includes(p.id)?'★':'☆'}</button></div>`:''}).join('')||'<p class="muted">Nenhum relatório concluído ainda.</p>'}</div></div>`:''}`}
window.selectScout=id=>{state.selectedScout=id;renderScouts()};
window.hireScout=()=>{const cost=scoutCost();if(state.budget<cost)return toast('Orçamento insuficiente.');const i=state.scouts.length,name=SCOUT_NAMES[i%SCOUT_NAMES.length]+' '+(i>=SCOUT_NAMES.length?Math.floor(i/SCOUT_NAMES.length+1):'');state.budget-=cost;state.scouts.push({id:uid(),name:name.trim(),level:clamp(1+Math.floor(i/2),1,10),region:'Brasil',accuracy:clamp(58+i*2,58,92),mission:null,reports:[]});save();renderScouts();renderTop();toast('Olheiro contratado.')};
window.sendScout=id=>{const s=state.scouts.find(x=>x.id===id);if(!s)return;const months=+$('#scoutMonths').value,region=$('#scoutRegion').value;s.mission={region,months,end:addDays(state.date,months*30)};s.reports=[];save();renderScouts();toast(`${s.name} iniciou viagem de ${months} meses.`)};
function processScoutMissions(){state.scouts.forEach(s=>{if(s.mission&&state.date>=s.mission.end){const pool=state.db.players.filter(p=>p.clubId!==state.clubId&&!club(p.clubId).guest);s.reports=shuffle(pool.slice()).slice(0,clamp(4+s.level,5,15)).map(p=>p.id);state.news.push({date:state.date,title:'Relatório de olheiro',body:`${s.name} voltou de ${s.mission.region} com ${s.reports.length} nomes.`});s.mission=null}})}

const REGIONAL_FIRST=['Lucas','Matteus','João','Gapreel','Petro','Ravail','Caeo','Davi','Henrice','Samuel','Arthur','Miguel','Gusdavu','Heitor','Luan','Danello','Vitor','Brumo','Niculas','Enzo'];
const REGIONAL_LAST=['Silva','Santista FC','Oliveira','Souza','Pereira','Costa','Fereera','Alves','Rodrigues','Lima','Gomes','Ribeiro','Carvalho','Moura','Teixeira','Barus','Freitas','Correia','Nogueira','Batista'];
function youthName(seed){return REGIONAL_FIRST[seed%REGIONAL_FIRST.length]+' '+REGIONAL_LAST[(seed*7+3)%REGIONAL_LAST.length]}
function generateYouthIntake(force=false){const ac=state.academy;if(!force&&ac.lastIntake&&new Date(state.date)-new Date(ac.lastIntake)<1000*60*60*24*90)return;const n=rnd(5,8);ac.candidates=[];for(let i=0;i<n;i++){const seed=Math.abs(hash(state.clubId+state.date+i+Math.random())),age=rnd(14,18),pos=pick(V03_POSITIONS.filter(x=>x!=='SA')),ovr=clamp(rnd(45,57)+Math.floor(ac.level*.8),45,65),pot=clamp(ovr+rnd(0,34)+Math.floor(ac.level*1.2),40,99),attrs=buildAttrs(pos,ovr,youthName(seed));ac.candidates.push({id:'yc_'+uid(),name:youthName(seed),age,pos,ovr,pot,attrs,traits:[labelAttr(Object.entries(attrs).sort((a,b)=>b[1]-a[1])[0][0])],morale:78,fitness:100})}ac.lastIntake=state.date;state.news.push({date:state.date,title:'Relatório da base',body:`Chegaram ${n} jovens para avaliação nas categorias de base.`})}
function renderAcademy(){const ac=state.academy,cost=ac.level>=10?0:2_000_000+ac.level*1_750_000;$('#academy').innerHTML=`<div class="page-head"><div><h1>Base</h1><p>Captação de jovens entre 14 e 18 anos com potencial variável.</p></div><button ${ac.level>=10?'disabled':''} onclick="upgradeAcademy()">Melhorar instalação ${ac.level<10?'• '+brl(cost):'MAX'}</button></div><div class="grid grid-3"><div class="card"><div class="academy-level">${ac.level}/10</div><div class="metric-label">Nível da base</div></div><div class="card"><div class="metric">${ac.roster.length}</div><div class="metric-label">Jovens contratados</div></div><div class="card"><div class="metric">${ac.lastIntake?fmtDate(ac.lastIntake):'—'}</div><div class="metric-label">Último relatório</div>${state.developerUnlocked?'<button style="margin-top:8px" onclick="generateYouthIntake(true);save();renderAcademy()">Gerar relatório (DEV)</button>':''}</div></div><div class="card" style="margin-top:13px"><h3>Relatório atual</h3>${ac.candidates.map(y=>`<div class="youth-card"><span class="pos">${y.pos}</span><div><b>${y.name}</b><div class="tiny muted">${y.age} anos • OVR ${y.ovr} • POT ${y.pot} • ${y.traits[0]}</div></div><div><button onclick="signYouth('${y.id}')">Contratar para base</button><button onclick="releaseYouth('${y.id}')">Dispensar</button></div></div>`).join('')||'<p class="muted">Nenhum relatório pendente.</p>'}</div><div class="card" style="margin-top:13px"><h3>Elenco da base</h3>${ac.roster.map(id=>{const p=player(id);return p?`<div class="market-card"><span class="pos">${p.pos}</span><div class="grow"><b>${p.name}</b><div class="tiny muted">${p.age} anos • OVR ${p.ovr} • POT ${p.pot}</div></div><button onclick="promoteYouth('${p.id}')">Subir ao profissional</button></div>`:''}).join('')||'<p class="muted">A base ainda não tem atletas contratados.</p>'}</div>`}
window.upgradeAcademy=()=>{const ac=state.academy;if(ac.level>=10)return;const cost=2_000_000+ac.level*1_750_000;if(state.budget<cost)return toast('Orçamento insuficiente.');state.budget-=cost;ac.level++;save();renderAcademy();renderTop();toast('Instalações da base melhoradas.')};
window.signYouth=id=>{const i=state.academy.candidates.findIndex(y=>y.id===id);if(i<0)return;const y=state.academy.candidates.splice(i,1)[0],p={...y,id:'y_'+uid(),clubId:state.clubId,positions:[y.pos],value:Math.round((y.ovr-35)**2*12000),wage:Math.round(y.ovr*y.ovr*2.5),contract:3,status:'Base',generated:true,unhappy:false,listed:false,loanFrom:null,form:70,season:{apps:0,goals:0,assists:0,ratingSum:0,ratingApps:0,cards:0},compStats:{},career:{apps:0,goals:0,assists:0}};p.positions=derivePositions(p);state.db.players.push(p);state.academy.roster.push(p.id);save();renderAcademy()};
window.releaseYouth=id=>{state.academy.candidates=state.academy.candidates.filter(y=>y.id!==id);save();renderAcademy()};
window.promoteYouth=id=>{state.academy.roster=state.academy.roster.filter(x=>x!==id);const p=player(id);if(p)p.status='Reserva';state.lineup=autoLineup(state.clubId,state.formation);save();renderAcademy();toast('Jogador promovido ao profissional.')};

window.openClub=id=>{const c=club(id),ps=teamPlayers(id),avg=Math.round(ps.reduce((s,p)=>s+p.ovr,0)/Math.max(1,ps.length)),val=ps.reduce((s,p)=>s+p.value,0),cid=c.division==='A'?'brA':c.division==='B'?'brB':null,t=cid?sortedTable(cid):[],pos=t.findIndex(r=>r.clubId===id)+1;modal(`<div class="modal-head"><div style="display:flex;gap:10px;align-items:center"><div class="club-badge" style="background:linear-gradient(135deg,${c.color},${c.color2})">${c.abbr}</div><div><h2 style="margin:0">${c.name}</h2><div class="tiny muted">${c.country} ${c.division?'• Série '+c.division:''}</div></div></div><button onclick="closeModal()">✕</button></div><div class="grid grid-4"><div class="card"><div class="metric">${avg}</div><div class="metric-label">OVR médio</div></div><div class="card"><div class="metric">${pos||'—'}º</div><div class="metric-label">Posição</div></div><div class="card"><div class="metric" style="font-size:18px">${brl(val)}</div><div class="metric-label">Valor do elenco</div></div><div class="card"><div class="metric">4-2-3-1</div><div class="metric-label">Formação base</div></div></div><div class="card" style="margin-top:12px"><h3>Elenco</h3>${ps.sort((a,b)=>b.ovr-a.ovr).map(p=>`<div class="market-card"><span class="pos">${p.pos}</span><div class="grow club-link" onclick="showMarketPlayer('${p.id}')"><b>${p.name}</b><div class="tiny muted">${p.age} anos • OVR ${p.ovr}</div></div></div>`).join('')}</div>`)};

function renderCalendar(){const view=state.calendarView||state.date.slice(0,7),[year,month1]=view.split('-').map(Number),month=month1-1,first=new Date(year,month,1),last=new Date(year,month+1,0),start=first.getDay(),cells=[];for(let i=0;i<start;i++)cells.push('');for(let day=1;day<=last.getDate();day++){const ds=new Date(year,month,day,12).toISOString().slice(0,10),fs=state.fixtures.filter(f=>f.date===ds&&(f.home===state.clubId||f.away===state.clubId));cells.push(`<div class="day ${ds===state.date?'today':''}" onclick="document.getElementById('targetDate').value='${ds}'"><div class="num">${day}</div>${fs.map(f=>`<div class="event">${comp(f.compId).name}<br><b>${club(f.home).abbr} x ${club(f.away).abbr}</b></div>`).join('')}</div>`)}$('#calendar').innerHTML=`<div class="page-head"><div><h1>Calendário</h1><p>${first.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</p></div><div class="calendar-tools"><button onclick="changeCalendarMonth(-1)">◀</button><button onclick="changeCalendarMonth(1)">▶</button><div class="field"><label>Avançar até</label><input type="date" id="targetDate" min="${state.date}" value="${state.date}"></div><button class="primary" onclick="advanceToDate()">Simular até a data</button></div></div><div class="card"><div class="calendar">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=>`<div class="tiny muted" style="text-align:center">${x}</div>`).join('')}${cells.map(x=>x||'<div></div>').join('')}</div></div>`}
window.changeCalendarMonth=delta=>{const [y,m]= (state.calendarView||state.date.slice(0,7)).split('-').map(Number),d=new Date(y,m-1+delta,1);state.calendarView=d.toISOString().slice(0,7);renderCalendar()};
window.advanceToDate=()=>{const target=$('#targetDate').value;if(!target||target<state.date)return toast('Escolha uma data futura.');advanceGameDays(target)};
function recoverByDays(days){teamPlayers(state.clubId).forEach(p=>{p.fitness=clamp(p.fitness+days*(1.9+p.attrs.fis/100),30,100);if(days>=2)p.morale=clamp(p.morale+rnd(-1,2),20,100)})}
function autoSimUserFixture(f){if(f.played)return;simulateFixture(f);const myHome=f.home===state.clubId,my=myHome?f.score.home:f.score.away,opp=myHome?f.score.away:f.score.home,result=my>opp?'win':my<opp?'loss':'draw';state.manager.played++;state.manager.gf+=my;state.manager.ga+=opp;if(result==='win')state.manager.wins++;else if(result==='loss')state.manager.losses++;else state.manager.draws++;updateStreak(result);state.clubConfidence=clamp(state.clubConfidence+(result==='win'?3:result==='loss'?-4:1),0,100);state.history.push({date:f.date,clubId:state.clubId,fixtureId:f.id,result,score:`${my}-${opp}`});state.news.push({date:f.date,title:`Simulação: ${club(f.home).name} ${f.score.home} x ${f.score.away} ${club(f.away).name}`,body:'Partida simulada pelo calendário.'})}
function advanceGameDays(target,includeUser=true){if(state.match&&!state.match.finished)return toast('Finalize a partida antes.');const start=state.date,days=Math.max(0,Math.round((new Date(target)-new Date(start))/86400000));simulateUntil(target,null);if(includeUser)state.fixtures.filter(f=>!f.played&&(f.home===state.clubId||f.away===state.clubId)&&f.date>start&&f.date<=target).sort((a,b)=>a.date.localeCompare(b.date)).forEach(autoSimUserFixture);recoverByDays(days);state.date=target;for(let i=0;i<Math.max(1,Math.floor(days/7));i++)aiMarketTick();processScoutMissions();generateYouthIntake(false);checkSeasonEnd();save();renderAll();toast(`Avançado até ${fmtDate(target)}.`)}
function advanceToNextEvent(){if(state.match&&!state.match.finished)return toast('Termine a partida antes de avançar.');if(state.offseason?.active){const target=addDays(state.date,7)>state.offseason.endDate?state.offseason.endDate:addDays(state.date,7);advanceGameDays(target,true);if(state.date>=state.offseason.endDate){startNextSeason();toast('Nova temporada iniciada!')}return}const n=nextUserFixture();if(!n){checkSeasonEnd();return}advanceGameDays(n.date,false);showPage('dashboard')}
window.advanceToNextEvent=advanceToNextEvent;

function dynamicGrowth(p){const apps=p.season?.apps||0,morale=p.morale||70,age=p.age;let delta=0;if(age<=21&&p.ovr<p.pot){delta=apps>=20?rnd(1,3):apps>=8?rnd(0,2):Math.random()<.35?1:0}else if(age<=25&&p.ovr<p.pot&&apps>=15)delta=rnd(0,2);if(p.loanFrom&&age<=23)delta+=Math.random()<.55?1:0;if(morale>=85&&apps>=12)delta+=Math.random()<.45?1:0;if(morale<45)delta-=Math.random()<.45?1:0;if(age>=31)delta-=Math.random()<(.25+(age-31)*.08)?rnd(1,2):0;if(age>=35)delta-=rnd(0,1);return clamp(delta,-3,3)}
function startNextSeason(){const before=state.db.players.map(p=>({id:p.id,apps:p.season?.apps||0}));startNextSeasonBaseV02();state.db.players.forEach(p=>{const prev=before.find(x=>x.id===p.id);const d=dynamicGrowth({...p,season:{apps:prev?.apps||0}});p.ovr=clamp(p.ovr+d,40,p.pot||99);Object.keys(p.attrs||{}).forEach(k=>p.attrs[k]=clamp(p.attrs[k]+(d>0?rnd(0,d):d<0?-rnd(0,Math.abs(d)):0),20,96));if(p.morale<50&&Math.random()<.35)p.ovr=clamp(p.ovr-1,40,99)});state.academy.candidates=[];generateYouthIntake(true);applyAgeFixes();save()}

function renderSettings(){const ac=state.academy;$('#settings').innerHTML=`<div class="page-head"><div><h1>Configurações</h1><p>Preferências da carreira e ferramentas de desenvolvedor.</p></div></div><div class="grid grid-2"><div class="card"><h3>Aparência</h3><button onclick="document.getElementById('themeToggle').click()">Alternar modo claro/escuro</button></div><div class="card"><h3>Desenvolvedor</h3>${state.developerUnlocked?`<div class="dev-box card"><div class="field"><label>Dinheiro</label><input id="devMoney" type="number" value="${state.budget}"></div><div class="field"><label>Nível da base (1-10)</label><input id="devAcademy" type="number" min="1" max="10" value="${ac.level}"></div><div class="field"><label>Ranking do manager (1-10)</label><input id="devRating" type="number" min="1" max="10" step="0.1" value="${state.manager.rating}"></div><button class="primary" onclick="applyDev()">Aplicar</button></div>`:`<div class="field"><label>Código</label><input id="devCode" type="password" placeholder="Digite o código"></div><button onclick="unlockDev()">Desbloquear</button>`}</div></div>`}
window.unlockDev=()=>{if($('#devCode').value!=='2205')return toast('Código incorreto.');state.developerUnlocked=true;save();renderSettings();toast('Modo desenvolvedor liberado.')};
window.applyDev=()=>{state.budget=Math.max(0,+$('#devMoney').value||0);state.academy.level=clamp(+$('#devAcademy').value||1,1,10);state.manager.rating=clamp(+$('#devRating').value||5,1,10);save();renderAll();toast('Valores de desenvolvedor aplicados.')};

// Player card: inclui OVR efetivo e clube clicável quando aplicável.
function playerDetail(p){if(!p)return '<p class="muted">Selecione um jogador.</p>';const base=playerDetailBaseV02(p);const c=club(p.clubId);return base.replace('</div><div class="grid grid-3"',`<div class="tiny muted club-link" onclick="openClub('${c.id}')">${c.name}</div></div><div class="grid grid-3"`)}

// Corrige renderização de substituições para permitir adaptações e mostrar energia.
function changeLiveFormation(form){const m=state.match,current=m.userXI.map(s=>player(s.playerId)),newSlots=getTacticSlots(form),used=new Set(),newXI=[];for(const s of newSlots){const cand=current.filter(p=>!used.has(p.id)&&canPlay(p,s.p)).sort((a,b)=>effectiveOvr(b,s.p)-effectiveOvr(a,s.p))[0];if(!cand)return toast('Não foi possível reorganizar os 11 jogadores.');used.add(cand.id);newXI.push({slotPos:s.p,x:s.x,y:s.y,playerId:cand.id})}m.userFormation=form;m.userXI=newXI;save();toast('Formação alterada.');renderSubModal()}
function renderSubModal(){const m=state.match;if(!m?.subModal)return;modal(`<div class="modal-head"><div><h2>🔄 Substituições e formação</h2><div class="tiny muted">${m.subModal.halftime?'Intervalo — não conta como janela.':`Subs ${m.subsUsed}/5 • janelas ${m.windowsUsed}/3`}</div></div><button onclick="closeSubs()">✕</button></div><div class="field" style="max-width:260px"><label>Formação</label><select id="liveForm">${tacticOptions().map(f=>`<option value="${f.key}" ${f.key===m.userFormation?'selected':''}>${f.label}</option>`).join('')}</select></div><div class="sub-layout"><div><h3>Titulares</h3><div class="sub-list">${m.userXI.map((s,i)=>{const p=player(s.playerId),energy=100-Math.round(m.fatigue[p.id]||0);return `<div class="sub-row ${m.subModal.selectedOut===i?'selected':''}"><span class="pos">${s.slotPos}</span><div class="grow"><b>${p.name}</b><div class="tiny muted">OVR efetivo ${effectiveOvr(p,s.slotPos)} • energia ${energy}%</div></div><button onclick="chooseSubOut(${i})">${m.subModal.selectedOut===i?'Selecionado':'Sair'}</button></div>`}).join('')}</div></div><div><h3>Reservas</h3><div class="sub-list">${m.userBench.map(id=>{const p=player(id),target=m.subModal.selectedOut!==null?m.userXI[m.subModal.selectedOut].slotPos:null;return `<div class="sub-row"><span class="pos">${p.pos}</span><div class="grow"><b>${p.name}</b><div class="tiny muted">OVR ${p.ovr}${target?` → ${effectiveOvr(p,target)} em ${target}`:''}</div></div><button ${target?'':'disabled'} onclick="confirmSub('${p.id}')">Entrar</button></div>`}).join('')}</div></div></div><div style="display:flex;justify-content:flex-end;margin-top:13px"><button onclick="closeSubs()">Voltar ao jogo</button></div>`);$('#liveForm').onchange=e=>changeLiveFormation(e.target.value)}

// Evolução de moral após performance individual.
function updatePlayerMatchStats(cid,compId,participants,result,gf,ga,goalEvents){updatePlayerMatchStatsBaseV02(cid,compId,participants,result,gf,ga,goalEvents);participants.forEach(id=>{const p=player(id);if(!p)return;const goals=goalEvents.filter(g=>g.scorerId===id).length,assists=goalEvents.filter(g=>g.assistId===id).length;p.morale=clamp(p.morale+(result==='win'?2:result==='loss'?-2:0)+goals*3+assists*2,20,100);p.form=clamp(p.form+(goals+assists>0?3:result==='win'?1:result==='loss'?-2:0),35,99)})}

applyAgeFixes();
