function v04Attrs(pos,ovr,name){
 const a=buildAttrs(pos,ovr,name); if(pos==='GOL') return a;
 const keys=['vel','fin','pas','dri','def','fis']; let sum=keys.reduce((s,k)=>s+a[k],0),target=ovr*6,diff=target-sum,i=0;
 while(diff!==0&&i<200){const k=keys[i%keys.length],step=diff>0?1:-1,n=a[k]+step;if(n>=20&&n<=99){a[k]=n;diff-=step}i++}
 return a;
}
function v04MakePlayer(c,raw,idx){
 const attrs=v04Attrs(raw.pos,raw.ovr,raw.name),p={id:`${c.id}_${slug(raw.name)}_${idx}`,clubId:c.id,name:raw.name,age:raw.age??clamp(18+(Math.abs(hash(raw.name+c.id))%16),18,35),pos:raw.pos,ovr:raw.ovr,pot:raw.pot??Math.min(93,raw.ovr+4),attrs,value:Math.round(Math.max(250000,(raw.ovr-50)*(raw.ovr-50)*52000*((raw.age||25)<24?1.3:1))),wage:Math.round(raw.ovr*raw.ovr*10.5),contract:2+(Math.abs(hash(raw.name))%3),morale:82,fitness:100,form:72,status:idx<11?'Titular':idx<20?'Rotação':'Reserva',generated:false,unhappy:false,listed:false,loanFrom:null,season:{apps:0,goals:0,assists:0,ratingSum:0,ratingApps:0,cards:0},compStats:{},career:{apps:0,goals:0,assists:0},devProgress:0,declineProgress:0};
 p.positions=derivePositions(p); if(raw.positions) p.positions=[...new Set([raw.pos,...raw.positions])]; const ranked=Object.entries(attrs).filter(([k])=>k!=='gk').sort((a,b)=>b[1]-a[1]);p.traits=[labelAttr(ranked[0][0]),labelAttr(ranked[1][0])];return p;
}
const _buildDatabaseV032=buildDatabase;
buildDatabase=function(){
 const db=_buildDatabaseV032();
 // Remove fillers genéricos dos clubes brasileiros. A base passa a gerar jovens apenas pelo sistema de categorias de base.
 db.players=db.players.filter(p=>{const c=db.clubs.find(x=>x.id===p.clubId);return !(c&&!c.guest&&p.generated)});
 const c=db.clubs.find(x=>x.id==='corinthians'); if(c){db.players=db.players.filter(p=>p.clubId!=='corinthians');V04_CORINTHIANS.forEach((r,i)=>db.players.push(v04MakePlayer(c,r,i)))}
 Object.entries(V04_EXTRA_ROSTERS).forEach(([cid,rs])=>{const cc=db.clubs.find(x=>x.id===cid);if(!cc)return;db.players=db.players.filter(p=>p.clubId!==cid);rs.forEach((r,i)=>db.players.push(v04MakePlayer(cc,r,i)))})
 db.clubs.forEach(c=>{const m=V04_STADIUMS[c.id];if(m){c.stadium=m[0];c.capacity=m[1];c.fanbase=m[2]}});
 return db;
};
function v04PatchExistingDb(){
 if(!state?.db)return; state.db.clubs.forEach(c=>{const m=V04_STADIUMS[c.id];if(m){c.stadium=m[0];c.capacity=m[1];c.fanbase=m[2]}});
 state.db.players=state.db.players.filter(p=>{const c=club(p.clubId);return !(c&&!c.guest&&p.generated&&String(p.id).includes('_base_'))});
 const c=club('corinthians'); if(c){
   const old=state.db.players.filter(p=>p.clubId==='corinthians'),byName=new Map(old.map(p=>[slug(p.name),p]));
   state.db.players=state.db.players.filter(p=>p.clubId!=='corinthians');
   V04_CORINTHIANS.forEach((r,i)=>{const prev=byName.get(slug(r.name)),p=v04MakePlayer(c,r,i);if(prev){p.season=prev.season||p.season;p.compStats=prev.compStats||{};p.career=prev.career||p.career;p.morale=prev.morale??p.morale;p.fitness=prev.fitness??p.fitness;p.form=prev.form??p.form;p.contract=prev.contract??p.contract;p.devProgress=prev.devProgress||0;p.declineProgress=prev.declineProgress||0}state.db.players.push(p)})
 }
 Object.entries(V04_EXTRA_ROSTERS).forEach(([cid,rs])=>{const cc=club(cid);if(!cc)return;const old=state.db.players.filter(p=>p.clubId===cid),byName=new Map(old.map(p=>[slug(p.name),p]));state.db.players=state.db.players.filter(p=>p.clubId!==cid);rs.forEach((r,i)=>{const prev=byName.get(slug(r.name)),p=v04MakePlayer(cc,r,i);if(prev){p.season=prev.season||p.season;p.compStats=prev.compStats||{};p.career=prev.career||p.career;p.morale=prev.morale??p.morale;p.fitness=prev.fitness??p.fitness;p.form=prev.form??p.form;p.contract=prev.contract??p.contract}state.db.players.push(p)})})
 Object.assign(AGE_FIXES,{'Thiago Silve':42,'Naimer':34,'Arascaete':32});
 applyAgeFixes();
}
autoLineup=function(cid,formation='4-2-3-1',poolOverride=null){const slots=getTacticSlots(formation),pool=(poolOverride||teamPlayers(cid)).slice(),used=new Set(),xi=[];const suitability=(p,s)=>{if(s.p==='GOL')return p.pos==='GOL'?200+p.ovr:-999;if(p.pos==='GOL')return-999;let v=effectiveOvr(p,s.p);if(p.pos===s.p)v+=15;else if((p.positions||[]).includes(s.p))v+=10;else if(POS_ZONE[p.pos]===POS_ZONE[s.p])v+=5;v+=(p.form||70)/35+(p.morale||70)/100;return v};slots.forEach(s=>{const p=pool.filter(x=>!used.has(x.id)).sort((a,b)=>suitability(b,s)-suitability(a,s))[0];if(p){used.add(p.id);xi.push({slotPos:s.p,x:s.x,y:s.y,playerId:p.id})}});const rest=pool.filter(p=>!used.has(p.id)).sort((a,b)=>(b.ovr+(b.form||70)/30)-(a.ovr+(a.form||70)/30));return{formation,xi,bench:rest.slice(0,9).map(p=>p.id),out:rest.slice(9).map(p=>p.id)}};
function v04Locate(pid){const i=state.lineup.xi.findIndex(x=>x.playerId===pid);if(i>=0)return{area:'xi',idx:i};let j=state.lineup.bench.indexOf(pid);if(j>=0)return{area:'bench',idx:j};j=state.lineup.out.indexOf(pid);if(j>=0)return{area:'out',idx:j};return null}
function v04SwapPlayers(a,b){if(!a||!b||a===b)return;const A=v04Locate(a),B=v04Locate(b);if(!A||!B)return;const get=L=>L.area==='xi'?state.lineup.xi[L.idx].playerId:state.lineup[L.area][L.idx],set=(L,id)=>{if(L.area==='xi')state.lineup.xi[L.idx].playerId=id;else state.lineup[L.area][L.idx]=id};set(A,b);set(B,a);state.selectedPlayer=b;state.tacticSelection=[];save();renderTactics();toast('Jogadores trocaram de lugar.')}
window.v04ConfirmSwap=()=>{const s=state.tacticSelection||[];if(s.length===2)v04SwapPlayers(s[0],s[1])};
window.v04SelectPlayer=(pid)=>{state.tacticSelection=state.tacticSelection||[];if(state.tacticSelection.includes(pid))state.tacticSelection=state.tacticSelection.filter(x=>x!==pid);else{state.tacticSelection.push(pid);if(state.tacticSelection.length>2)state.tacticSelection.shift()}state.selectedPlayer=pid;renderTactics()};
window.v04MoveToPos=(pid,pos)=>{const L=v04Locate(pid);if(!L||L.area!=='xi')return;const p=player(pid);if(pos==='GOL'&&p.pos!=='GOL')return toast('Somente goleiros podem jogar no gol.');if(p.pos==='GOL'&&pos!=='GOL')return toast('Goleiro não pode atuar na linha.');const [x,y]=V04_POS_COORD[pos],same=state.lineup.xi.filter(s=>s.slotPos===pos).length;state.lineup.xi[L.idx].slotPos=pos;state.lineup.xi[L.idx].x=clamp(x+(same%2?8:-8)*Math.floor((same+1)/2),8,92);state.lineup.xi[L.idx].y=y;save();renderTactics();toast(`${p.name} reposicionado para ${pos}.`)};
function v04ReflowFormation(form){const slots=getTacticSlots(form),current=state.lineup.xi.map(s=>player(s.playerId)).filter(Boolean),used=new Set(),newXI=[];const score=(p,s)=>effectiveOvr(p,s.p)+(POS_ZONE[p.pos]===POS_ZONE[s.p]?4:0)+(p.positions?.includes(s.p)?5:0)+(p.pos===s.p?7:0);const ordered=slots.slice().sort((a,b)=>(a.p==='GOL'?-1:b.p==='GOL'?1:0));for(const s of ordered){const cand=current.filter(p=>!used.has(p.id)&&(s.p!=='GOL'||p.pos==='GOL')&&(s.p==='GOL'||p.pos!=='GOL')).sort((a,b)=>score(b,s)-score(a,s))[0];if(cand){used.add(cand.id);newXI.push({slotPos:s.p,x:s.x,y:s.y,playerId:cand.id})}}if(newXI.length!==11)return toast('Não foi possível reorganizar os 11 atuais.');newXI.sort((a,b)=>slots.findIndex(s=>s.p===a.slotPos&&s.x===a.x)-slots.findIndex(s=>s.p===b.slotPos&&s.x===b.x));state.formation=form;state.lineup.formation=form;state.lineup.xi=newXI;save();renderTactics()}
function v04ZoneLabels(p){const entries=[['GOL',50,92],['LE',13,73],['ZAG',50,77],['LD',87,73],['VOL',50,64],['MLE',13,51],['MC',50,52],['MLD',87,51],['MAT',50,41],['PE',17,29],['SA',50,30],['PD',83,29],['ATA',50,16]];return `<div class="zone-guides">${entries.map(([pos,x,y])=>`<button class="zone-pos ${(p&&(p.pos===pos||p.positions?.includes(pos)))?'ok':''}" style="left:${x}%;top:${y}%" data-drop-pos="${pos}" onclick="event.stopPropagation();${p?`v04MoveToPos('${p.id}','${pos}')`:''}">${pos}</button>`).join('')}</div>`}
function v04PlayerNode(pid,area,idx,slot=null){const p=player(pid);if(!p)return'';const sel=(state.tacticSelection||[]).includes(pid),eff=slot?effectiveOvr(p,slot.slotPos):p.ovr;const core=`data-player-id="${p.id}" data-area="${area}" data-index="${idx}"`;if(area==='xi')return `<div class="slot tactic-player ${sel?'selected-player':''}" ${core} style="left:${slot.x}%;top:${slot.y}%"><button onclick="event.stopPropagation();v04SelectPlayer('${p.id}')"><div class="slot-bubble">${slot.slotPos}</div><small>${p.name} • ${eff}</small></button></div>`;return `<div class="player-chip tactic-player ${sel?'selected-player':''}" ${core} onclick="v04SelectPlayer('${p.id}')"><span class="pos">${p.pos}</span><div class="grow"><b>${p.name}</b><span class="tiny muted">OVR ${p.ovr} • ${(p.positions||[p.pos]).join('/')}</span></div><span class="drag-handle">⠿</span></div>`}
let v04Drag=null;
function v04BindDrag(){document.querySelectorAll('#tactics .tactic-player').forEach(el=>{el.onpointerdown=e=>{if(e.button!==undefined&&e.button!==0)return;const pid=el.dataset.playerId;v04Drag={pid,startX:e.clientX,startY:e.clientY,moved:false,ghost:null};el.setPointerCapture?.(e.pointerId)};el.onpointermove=e=>{if(!v04Drag||v04Drag.pid!==el.dataset.playerId)return;const d=Math.hypot(e.clientX-v04Drag.startX,e.clientY-v04Drag.startY);if(d<7&&!v04Drag.moved)return;v04Drag.moved=true;if(!v04Drag.ghost){const g=el.cloneNode(true);g.classList.add('drag-ghost');document.body.appendChild(g);v04Drag.ghost=g;document.querySelector('.tactic-pitch')?.classList.add('player-active')}v04Drag.ghost.style.left=e.clientX+'px';v04Drag.ghost.style.top=e.clientY+'px'};el.onpointerup=e=>{if(!v04Drag||v04Drag.pid!==el.dataset.playerId)return;const d=v04Drag;if(d.moved){d.ghost?.remove();document.querySelector('.tactic-pitch')?.classList.remove('player-active');const target=document.elementFromPoint(e.clientX,e.clientY)?.closest?.('[data-player-id],[data-drop-pos]');if(target?.dataset.playerId&&target.dataset.playerId!==d.pid)v04SwapPlayers(d.pid,target.dataset.playerId);else if(target?.dataset.dropPos)v04MoveToPos(d.pid,target.dataset.dropPos)}v04Drag=null};})}
renderTactics=function(){repairGameState();if(!state.lineup||state.lineup.xi.length!==11)state.lineup=autoLineup(state.clubId,state.formation);state.tacticSelection=state.tacticSelection||[];const sel=player(state.tacticSelection.at(-1))||player(state.selectedPlayer)||player(state.lineup.xi[0]?.playerId),opts=tacticOptions(),dark=state.tacticSelection.length?' player-active':'';$('#tactics').innerHTML=`<div class="page-head"><div><h1>Táticas</h1><p>Clique em dois jogadores e use ⇄ para trocar, ou arraste com mouse/toque. Sua escalação fica salva para as próximas partidas.</p></div><div style="display:flex;gap:7px"><button onclick="openCustomTactic()">+ Criar tática</button><select id="formationSelect" style="width:190px">${opts.map(f=>`<option value="${f.key}" ${f.key===state.formation?'selected':''}>${f.label}</option>`).join('')}</select></div></div>${state.tacticSelection.length===2?`<div class="swap-bar"><b>${player(state.tacticSelection[0])?.name}</b><button class="primary" onclick="v04ConfirmSwap()">⇄ Trocar jogadores</button><b>${player(state.tacticSelection[1])?.name}</b></div>`:''}<div class="grid" style="grid-template-columns:minmax(0,1.12fr) minmax(330px,.88fr)"><div class="card"><div class="tactic-pitch${dark}"><div class="pitch-midline"></div><div class="pitch-circle"></div><div class="penalty top"></div><div class="penalty bottom"></div><div class="goal top"></div><div class="goal bottom"></div>${v04ZoneLabels(sel)}${state.lineup.xi.map((s,i)=>v04PlayerNode(s.playerId,'xi',i,s)).join('')}</div><div class="tiny muted" style="margin-top:8px">Ao selecionar/arrastar um atleta, posições naturais/secundárias ficam verdes; outras continuam cinza e aplicam perda de OVR.</div><div class="grid grid-3" style="margin-top:10px"><div><label class="tiny muted">Pressão</label><input type="range" min="20" max="90" value="${state.pressing}" id="pressing"></div><div><label class="tiny muted">Linha defensiva</label><input type="range" min="20" max="90" value="${state.line}" id="line"></div><div><label class="tiny muted">Ritmo</label><input type="range" min="20" max="90" value="${state.tempo}" id="tempo"></div></div><div class="field" style="margin-top:10px"><label>Mentalidade</label><select id="mentalitySelect">${['Ultradefensivo','Defensivo','Equilibrado','Ofensivo','Ultraofensivo'].map(x=>`<option ${x===state.mentality?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="grid"><div class="card"><h3>Reservas</h3><div class="bench-grid">${state.lineup.bench.filter(id=>player(id)).map((id,i)=>v04PlayerNode(id,'bench',i)).join('')||'<span class="muted tiny">Sem reservas.</span>'}</div><h3 style="margin-top:14px">Não relacionados</h3><div class="bench-grid">${state.lineup.out.filter(id=>player(id)).map((id,i)=>v04PlayerNode(id,'out',i)).join('')||'<span class="muted tiny">Sem não relacionados.</span>'}</div></div><div class="card player-panel" style="position:static">${playerDetail(sel)}</div></div></div>`;$('#formationSelect').onchange=e=>v04ReflowFormation(e.target.value);$('#mentalitySelect').onchange=e=>{state.mentality=e.target.value;save()};['pressing','line','tempo'].forEach(id=>{const el=$('#'+id);if(el)el.onchange=e=>{state[id]=+e.target.value;save()}});v04BindDrag()};

const _initialStateV032=initialState;
initialState=function(manager,clubId,opts){const s=_initialStateV032(manager,clubId,opts);s.version='0.4';s.clubConfidence=100;s.fanConfidence=100;s.financeLedger=[];s.objectives=[];s.lastFinanceDate=s.date;s.lastDevelopmentMonth=s.date.slice(0,7);s.tacticSelection=[];s.snapshotV04Applied=true;return s};
function v04EnsureState(){if(!state)return;state.version='0.4';state.fanConfidence=Number.isFinite(+state.fanConfidence)?+state.fanConfidence:100;if((state.manager?.played||0)===0)state.clubConfidence=100;state.financeLedger=state.financeLedger||[];state.objectives=state.objectives||[];state.lastFinanceDate=state.lastFinanceDate||state.date;state.lastDevelopmentMonth=state.lastDevelopmentMonth||state.date.slice(0,7);state.tacticSelection=[];state.academy=state.academy||{level:1,lastIntake:null,candidates:[],roster:[]};state.academy.candidates=state.academy.candidates||[];state.academy.roster=state.academy.roster||[];if(!state.snapshotV04Applied){v04PatchExistingDb();state.snapshotV04Applied=true}if(!state.lineup||state.lineup.xi.some(s=>!player(s.playerId)))state.lineup=autoLineup(state.clubId,state.formation);state.wageSpent=teamPlayers(state.clubId).reduce((s,p)=>s+(p.wage||0),0);v04SetObjectives()}
const _repairV032=repairGameState;repairGameState=function(){try{_repairV032()}catch(e){console.warn(e)}v04EnsureState()};
function v04SetObjectives(){if(state.objectives?.length)return;const rep=club(state.clubId)?.rep||70,div=club(state.clubId)?.division;state.objectives=[{id:'league',title:rep>=85?'Disputar o título brasileiro':rep>=78?'Terminar no G8':div==='A'?'Permanecer na Série A':'Brigar pelo acesso',weight:45},{id:'cup',title:rep>=82?'Chegar às semifinais da Copa nacional':'Chegar às oitavas da Copa nacional',weight:25},{id:'finance',title:'Manter as finanças sob controle',weight:20},{id:'squad',title:'Manter o elenco competitivo e com boa moral',weight:10}]}
function v04ObjectiveStatus(o){if(o.id==='finance')return state.budget>=0?100:20;if(o.id==='squad'){const ps=teamPlayers(state.clubId);return Math.round(ps.reduce((s,p)=>s+(p.morale||70),0)/Math.max(1,ps.length))}if(o.id==='league'){const id=club(state.clubId).division==='A'?'brA':'brB',row=sortedTable(id).find(r=>r.clubId===state.clubId);if(!row||!row.p)return 70;const pos=sortedTable(id).findIndex(r=>r.clubId===state.clubId)+1;return clamp(105-pos*4,15,100)}return 70}
function v04RecalcConfidence(){const obj=state.objectives||[];const objectiveScore=obj.reduce((s,o)=>s+v04ObjectiveStatus(o)*o.weight,0)/Math.max(1,obj.reduce((s,o)=>s+o.weight,0));const recent=(state.history||[]).filter(h=>h.result).slice(-8),resultScore=recent.length?recent.reduce((s,h)=>s+(h.result==='win'?100:h.result==='draw'?58:22),0)/recent.length:100;const finance=state.budget>=0?100:20;state.clubConfidence=clamp(Math.round(objectiveScore*.45+resultScore*.4+finance*.15),0,100);const demanding=clamp((club(state.clubId).rep-65)/30,0,1),fanBase=recent.length?recent.reduce((s,h)=>s+(h.result==='win'?100:h.result==='draw'?(60-10*demanding):(28-16*demanding)),0)/recent.length:100;state.fanConfidence=clamp(Math.round(fanBase),0,100)}
function renderObjectives(){v04SetObjectives();$('#objectives').innerHTML=`<div class="page-head"><div><h1>Objetivos</h1><p>A diretoria avalia resultados, metas esportivas e gestão financeira.</p></div><span class="tag">Diretoria ${state.clubConfidence}% • Torcida ${state.fanConfidence}%</span></div><div class="grid grid-2">${state.objectives.map(o=>{const v=v04ObjectiveStatus(o);return `<div class="card"><div style="display:flex;justify-content:space-between;gap:10px"><div><h3>${o.title}</h3><div class="tiny muted">Peso na avaliação: ${o.weight}%</div></div><b>${v}%</b></div><div class="progress ${v>=70?'green':v<45?'warn':''}" style="margin-top:12px"><span style="width:${v}%"></span></div></div>`}).join('')}</div><div class="card" style="margin-top:13px"><h3>Como a confiança funciona</h3><p class="small muted">A torcida reage principalmente às últimas partidas e é mais exigente em clubes de maior reputação. A diretoria considera resultados, objetivos e saúde financeira.</p></div>`}
const _renderPageV032=renderPage;renderPage=function(id){if(id==='objectives')return renderObjectives();return _renderPageV032(id)};
function v04BuildNav(){const nav=$('#nav');if(!nav)return;nav.innerHTML=`<div class="nav-group open"><button class="nav-group-title" type="button">Início <span>⌄</span></button><div class="nav-group-items"><button data-page="dashboard">🏠 <span class="label">Painel</span></button><button data-page="squad">👥 <span class="label">Elenco</span></button><button data-page="tactics">📋 <span class="label">Táticas</span></button><button data-page="competitions">🏆 <span class="label">Competições</span></button><button data-page="match">⚽ <span class="label">Partida</span></button></div></div><div class="nav-group open"><button class="nav-group-title" type="button">Gestão <span>⌄</span></button><div class="nav-group-items"><button data-page="transfers">💼 <span class="label">Transferências</span></button><button data-page="scouts">🔎 <span class="label">Olheiros</span></button><button data-page="academy">🌱 <span class="label">Base</span></button><button data-page="calendar">📅 <span class="label">Calendário</span></button><button data-page="finances">💰 <span class="label">Finanças</span></button></div></div><div class="nav-group open"><button class="nav-group-title" type="button">Carreira <span>⌄</span></button><div class="nav-group-items"><button data-page="jobs">🪪 <span class="label">Vagas</span></button><button data-page="objectives">🎯 <span class="label">Objetivos</span></button><button data-page="settings">⚙️ <span class="label">Configurações</span></button></div></div>`;nav.querySelectorAll('.nav-group-title').forEach(b=>b.onclick=e=>{e.stopPropagation();b.parentElement.classList.toggle('open')})}
