function v04Stadium(cid){const c=club(cid),m=V04_STADIUMS[cid];return c?.stadium||m?.[0]||'Estádio local'}
const _renderMatchV032=renderMatch;renderMatch=function(){_renderMatchV032();const f=state.match?state.fixtures.find(x=>x.id===state.match.fixtureId):nextUserFixture();if(!f)return;const home=club(f.home),venue=v04Stadium(f.home),head=$('#match .page-head');if(head&&!$('#matchVenue')){const d=document.createElement('div');d.id='matchVenue';d.className='venue-line';d.innerHTML=`🏟️ <b>${venue}</b> • mando de ${home.name}`;head.insertAdjacentElement('afterend',d)}};
function v04GateIncome(f){if(!f||f.financeApplied||f.home!==state.clubId)return;const c=club(state.clubId),cap=c.capacity||25000,fans=c.fanbase||1000000,occ=clamp(.48+(state.fanConfidence/100)*.48+(club(f.away).rep-c.rep)/400,.35,1),attendance=Math.round(Math.min(cap,fans*.015)*occ),ticket=Math.round(55+c.rep*.5),income=attendance*ticket;state.budget+=income;state.financeLedger.push({date:f.date,type:'Bilheteria',value:income,detail:`${attendance.toLocaleString('pt-BR')} torcedores • ${v04Stadium(c.id)}`});f.financeApplied=true}
function v04EconomyBetween(start,target){const a=new Date(start+'T12:00:00'),b=new Date(target+'T12:00:00');let cur=new Date(a);cur.setDate(cur.getDate()+7);while(cur<=b){const c=club(state.clubId),fans=c.fanbase||1000000,merch=Math.round(fans*(.012+.018*state.fanConfidence/100));state.budget+=merch;state.financeLedger.push({date:cur.toISOString().slice(0,10),type:'Produtos e camisas',value:merch,detail:`Confiança da torcida ${state.fanConfidence}%`});cur.setDate(cur.getDate()+7)}
 let m=new Date(a.getFullYear(),a.getMonth()+1,1,12);while(m<=b){const payroll=teamPlayers(state.clubId).reduce((s,p)=>s+(p.wage||0),0);state.budget-=payroll;state.financeLedger.push({date:m.toISOString().slice(0,10),type:'Folha salarial',value:-payroll,detail:'Pagamento mensal de salários'});m=new Date(m.getFullYear(),m.getMonth()+1,1,12)}}
const _finalizeFixtureV032=finalizeFixtureResult;finalizeFixtureResult=function(f,hg,ag,details=null){const r=_finalizeFixtureV032(f,hg,ag,details);v04GateIncome(f);return r};
function renderFinances(){const spent=state.transactions.filter(t=>['Compra','Empréstimo'].includes(t.type)).reduce((s,t)=>s+(t.value||0),0),sales=state.transactions.filter(t=>t.type==='Venda').reduce((s,t)=>s+(t.value||0),0),merch=(state.financeLedger||[]).filter(x=>x.type==='Produtos e camisas').reduce((s,x)=>s+x.value,0),gate=(state.financeLedger||[]).filter(x=>x.type==='Bilheteria').reduce((s,x)=>s+x.value,0),wages=teamPlayers(state.clubId).reduce((s,p)=>s+(p.wage||0),0);$('#finances').innerHTML=`<div class="page-head"><div><h1>Finanças</h1><p>Receitas de estádio/produtos, mercado e folha salarial.</p></div></div><div class="grid grid-4"><div class="card"><div class="metric">${brl(state.budget)}</div><div class="metric-label">Caixa</div></div><div class="card"><div class="metric">${brl(wages)}</div><div class="metric-label">Folha mensal estimada</div></div><div class="card"><div class="metric">${brl(gate)}</div><div class="metric-label">Bilheteria na temporada</div></div><div class="card"><div class="metric">${brl(merch)}</div><div class="metric-label">Produtos e camisas</div></div></div><div class="grid grid-2" style="margin-top:13px"><div class="card"><h3>Mercado</h3><div class="fixture"><span>Contratações</span><b>${brl(spent)}</b></div><div class="fixture"><span>Vendas</span><b>${brl(sales)}</b></div></div><div class="card"><h3>Confiança e receita</h3><div class="small">Torcida <b>${state.fanConfidence}%</b></div><div class="progress green" style="margin-top:7px"><span style="width:${state.fanConfidence}%"></span></div><p class="tiny muted">Confiança alta aumenta ocupação do estádio e vendas semanais de produtos.</p></div></div><div class="card" style="margin-top:13px"><h3>Livro-caixa</h3>${(state.financeLedger||[]).slice().reverse().slice(0,40).map(t=>`<div class="fixture"><span class="tag">${t.type}</span><div class="teams"><b>${t.detail||''}</b><div class="tiny muted">${fmtDate(t.date)}</div></div><b class="${t.value>=0?'positive':'negative'}">${t.value>=0?'+':''}${brl(t.value)}</b></div>`).join('')||'<p class="muted">Ainda sem lançamentos.</p>'}</div>`}

function v04OverallFromAttrs(p){if(p.pos==='GOL')return clamp(Math.round((p.attrs.gk*2+p.attrs.pas+p.attrs.fis+p.attrs.vel)/5),40,99);const k=['vel','fin','pas','dri','def','fis'];return clamp(Math.round(k.reduce((s,x)=>s+(p.attrs[x]||50),0)/6),40,99)}
function v04AdjustAttrs(p,dir){const keys=p.pos==='GOL'?['gk','pas','fis','vel']:['vel','fin','pas','dri','def','fis'],rank=dir>0?keys.slice().sort((a,b)=>p.attrs[a]-p.attrs[b]):keys.slice().sort((a,b)=>p.attrs[b]-p.attrs[a]);for(let i=0;i<3;i++){const k=rank[i%rank.length];p.attrs[k]=clamp(p.attrs[k]+dir,20,99)}p.ovr=v04OverallFromAttrs(p)}
function v04MonthlyDevelopment(){const key=state.date.slice(0,7);if(state.lastDevelopmentMonth===key)return;const startYear=state.seasonStartYear,month=+state.date.slice(5,7),monthsElapsed=Math.max(1,month);state.db.players.forEach(p=>{p.devProgress=p.devProgress||0;p.declineProgress=p.declineProgress||0;const apps=p.season?.apps||0,playRate=clamp(apps/Math.max(1,monthsElapsed*4),0,1),perf=clamp(((p.form||70)-60)/40,0,1),happy=clamp(((p.morale||70)-50)/50,0,1);if(p.age<=29){let speed=p.age<=21?19:p.age<=24?13:p.age<=27?8:4;speed*=.35+.65*playRate;speed*=.7+.3*perf;speed*=.75+.25*happy;p.devProgress+=speed;const threshold=p.ovr<(p.pot||p.ovr)?100:200;while(p.devProgress>=threshold&&p.ovr<99){const before=p.ovr;for(let i=0;i<12&&p.ovr===before;i++)v04AdjustAttrs(p,1);p.devProgress-=threshold}}
 if(p.age>=30){let fall=(p.age===30?3:4+(p.age-30)*1.25)*(1-.65*playRate)*(1-.3*perf);p.declineProgress+=Math.max(.5,fall);while(p.declineProgress>=100&&p.ovr>45){const before=p.ovr;for(let i=0;i<12&&p.ovr===before;i++)v04AdjustAttrs(p,-1);p.declineProgress-=100}}
 });state.lastDevelopmentMonth=key}
function v04ApplyFatigueToRoster(ids,intensity=1){ids.forEach(id=>{const p=player(id);if(!p)return;const ageFactor=p.age>=34?1.28:p.age>=30?1.15:p.age<=21?.86:1,power=clamp((72-(p.attrs?.fis||70))*.08+8,5,13)*ageFactor*intensity;p.fitness=clamp((p.fitness??100)-power,25,100)})}
function recoverByDays(days){teamPlayers(state.clubId).forEach(p=>{const ageFactor=p.age>=34?0.72:p.age>=30?0.84:p.age<=21?1.12:1;p.fitness=clamp((p.fitness??100)+days*(2.1+(p.attrs.fis||70)/70)*ageFactor,25,100);if(days>=2)p.morale=clamp(p.morale+rnd(-1,2),20,100)})}
const _finishMatchV032=finishMatch;finishMatch=function(){_finishMatchV032();v04RecalcConfidence();save();renderTop()};
const _autoSimUserV032=autoSimUserFixture;autoSimUserFixture=function(f){const ids=state.lineup?.xi?.map(x=>x.playerId)||[];_autoSimUserV032(f);v04ApplyFatigueToRoster(ids,.9);v04RecalcConfidence()};
