function v04TeamQuality(cid){const ps=teamPlayers(cid),line=autoLineup(cid,'4-2-3-1').xi.map(s=>player(s.playerId)).filter(Boolean),bench=ps.slice().sort((a,b)=>b.ovr-a.ovr).slice(11,18);const xi=line.length?line.reduce((s,p)=>s+p.ovr*(.72+(p.form||70)/250)*(.75+(p.morale||70)/300)*(.75+(p.fitness||90)/400),0)/line.length:(club(cid).rep||65),depth=bench.length?bench.reduce((s,p)=>s+p.ovr,0)/bench.length:xi;return xi*.72+depth*.13+(club(cid).rep||70)*.15}
simulateFixture=function(f){if(f.played)return;const hq=v04TeamQuality(f.home),aq=v04TeamQuality(f.away),diff=(hq-aq)/7,homeAdv=.22,lambdaH=clamp(1.22+homeAdv+diff*.48,.15,3.6),lambdaA=clamp(1.04-diff*.48,.12,3.3),hg=poisson(lambdaH),ag=poisson(lambdaA);finalizeFixtureResult(f,hg,ag);const hxi=autoLineup(f.home).xi.map(s=>s.playerId),axi=autoLineup(f.away).xi.map(s=>s.playerId),events=[];for(let i=0;i<hg;i++){const sc=weightedScorerGeneric(f.home,hxi),a=weightedAssistGeneric(f.home,hxi,sc.id);events.push({clubId:f.home,scorerId:sc.id,assistId:a?.id||null})}for(let i=0;i<ag;i++){const sc=weightedScorerGeneric(f.away,axi),a=weightedAssistGeneric(f.away,axi,sc.id);events.push({clubId:f.away,scorerId:sc.id,assistId:a?.id||null})}const hr=hg>ag?'win':hg<ag?'loss':'draw',ar=hg>ag?'loss':hg<ag?'win':'draw';updatePlayerMatchStats(f.home,f.compId,hxi,hr,hg,ag,events);updatePlayerMatchStats(f.away,f.compId,axi,ar,ag,hg,events)};

const _generateYouthV032=generateYouthIntake;generateYouthIntake=function(force=false){const ac=state.academy;if(!force&&ac.lastIntake&&state.date.slice(0,7)===ac.lastIntake.slice(0,7))return;if(ac.candidates.length>=45)return;const room=45-ac.candidates.length,n=Math.min(room,rnd(Math.max(3,3+Math.floor(ac.level/3)),Math.max(5,6+Math.floor(ac.level/2))));for(let i=0;i<n;i++){const seed=Math.abs(hash(state.clubId+state.date+i+Math.random())),age=rnd(14,18),pos=pick(V03_POSITIONS.filter(x=>x!=='SA')),ovr=clamp(rnd(45,56)+Math.floor(ac.level*.9),45,65),pot=clamp(ovr+rnd(0,34)+Math.floor(ac.level*1.25),40,99),attrs=v04Attrs(pos,ovr,youthName(seed));ac.candidates.push({id:'yc_'+uid(),name:youthName(seed),age,pos,ovr,pot,attrs,traits:[labelAttr(Object.entries(attrs).sort((a,b)=>b[1]-a[1])[0][0])],morale:78,fitness:100,devProgress:0,declineProgress:0})}ac.lastIntake=state.date;state.news.push({date:state.date,title:'Relatório mensal da base',body:`Chegaram ${n} novos jovens para avaliação. Relatórios: ${ac.candidates.length}/45.`})};
window.signYouth=id=>{if(state.academy.roster.length>=45)return toast('A base atingiu o limite de 45 jogadores.');const i=state.academy.candidates.findIndex(y=>y.id===id);if(i<0)return;const y=state.academy.candidates.splice(i,1)[0],p={...y,id:'y_'+uid(),clubId:state.clubId,positions:[y.pos],value:Math.round((y.ovr-35)**2*12000),wage:Math.round(y.ovr*y.ovr*2.5),contract:3,status:'Base',generated:true,unhappy:false,listed:false,loanFrom:null,form:70,season:{apps:0,goals:0,assists:0,ratingSum:0,ratingApps:0,cards:0},compStats:{},career:{apps:0,goals:0,assists:0}};p.positions=derivePositions(p);state.db.players.push(p);state.academy.roster.push(p.id);save();renderAcademy()};
window.releaseAcademyPlayer=id=>{state.academy.roster=state.academy.roster.filter(x=>x!==id);state.db.players=state.db.players.filter(x=>x.id!==id);save();renderAcademy();toast('Jogador dispensado da base.')};
function renderAcademy(){const ac=state.academy,cost=ac.level>=10?0:2_000_000+ac.level*1_750_000;$('#academy').innerHTML=`<div class="page-head"><div><h1>Base</h1><p>Relatórios mensais • limite 45 em observação e 45 contratados.</p></div><button ${ac.level>=10?'disabled':''} onclick="upgradeAcademy()">Melhorar instalação ${ac.level<10?'• '+brl(cost):'MAX'}</button></div><div class="grid grid-4"><div class="card"><div class="academy-level">${ac.level}/10</div><div class="metric-label">Nível da base</div></div><div class="card"><div class="metric">${ac.candidates.length}/45</div><div class="metric-label">Relatórios pendentes</div></div><div class="card"><div class="metric">${ac.roster.length}/45</div><div class="metric-label">Elenco da base</div></div><div class="card"><div class="metric">${ac.lastIntake?fmtDate(ac.lastIntake):'—'}</div><div class="metric-label">Último relatório</div></div></div><div class="card" style="margin-top:13px"><h3>Relatório atual</h3>${ac.candidates.map(y=>`<div class="youth-card"><span class="pos">${y.pos}</span><div><b>${y.name}</b><div class="tiny muted">${y.age} anos • OVR ${y.ovr} • POT ${y.pot} • ${y.traits[0]}</div></div><div><button onclick="signYouth('${y.id}')">Contratar para base</button><button onclick="releaseYouth('${y.id}')">Dispensar relatório</button></div></div>`).join('')||'<p class="muted">Nenhum relatório pendente.</p>'}</div><div class="card" style="margin-top:13px"><h3>Elenco da base</h3>${ac.roster.map(id=>{const p=player(id);return p?`<div class="market-card"><span class="pos">${p.pos}</span><div class="grow"><b>${p.name}</b><div class="tiny muted">${p.age} anos • OVR ${p.ovr} • POT ${p.pot}</div></div><button onclick="promoteYouth('${p.id}')">Subir ao profissional</button><button class="danger" onclick="releaseAcademyPlayer('${p.id}')">Dispensar</button></div>`:''}).join('')||'<p class="muted">A base ainda não tem atletas contratados.</p>'}</div>`}

function v04RenewModal(pid){const p=player(pid);if(!p||p.clubId!==state.clubId)return;modal(`<div class="modal-head"><div><h2>Renovar contrato • ${p.name}</h2><div class="tiny muted">Moral ${p.morale}% • contrato atual ${p.contract} ano(s)</div></div><button onclick="closeModal()">✕</button></div><div class="grid grid-2"><div class="field"><label>Anos adicionais (1–4)</label><input id="renewYears" type="number" min="1" max="4" value="2"></div><div class="field"><label>Novo salário mensal</label><input id="renewWage" type="number" min="0" value="${Math.round(p.wage*1.08)}"></div></div><div class="field"><label>Luvas</label><input id="renewBonus" type="number" min="0" value="${Math.round(p.wage*3)}"></div><button class="primary" onclick="v04SubmitRenew('${p.id}')">Enviar proposta</button>`)}
window.v04RenewModal=v04RenewModal;window.v04SubmitRenew=pid=>{const p=player(pid),yrs=clamp(+$('#renewYears').value||1,1,4),w=+$('#renewWage').value||0,b=+$('#renewBonus').value||0;if(b>state.budget)return toast('Caixa insuficiente para as luvas.');const wageRatio=w/Math.max(1,p.wage),chance=clamp(.18+(p.morale/100)*.52+(wageRatio-1)*.28+(p.contract<=1?.08:0),.08,.96);if(Math.random()>chance)return toast('O jogador recusou a renovação.');state.budget-=b;p.wage=w;p.contract=clamp(p.contract+yrs,1,6);p.morale=clamp(p.morale+4,0,100);state.transactions.push({date:state.date,type:'Renovação',player:p.name,value:b});state.financeLedger.push({date:state.date,type:'Luvas de renovação',value:-b,detail:p.name});state.wageSpent=teamPlayers(state.clubId).reduce((s,x)=>s+x.wage,0);closeModal();save();renderSquad();toast('Contrato renovado!')};
const _playerDetailV032=playerDetail;playerDetail=function(p){let html=_playerDetailV032(p);if(p&&p.clubId===state.clubId)html+=`<div style="margin-top:14px"><button class="primary" onclick="v04RenewModal('${p.id}')">Renovar contrato</button></div>`;return html};

const _renderDashboardV032=renderDashboard;renderDashboard=function(){v04RecalcConfidence();_renderDashboardV032();const cards=$('#dashboard .grid.grid-4');if(cards&&!$('#fanTrustCard')){const d=document.createElement('div');d.className='card';d.id='fanTrustCard';d.innerHTML=`<div class="metric">${state.fanConfidence}%</div><div class="metric-label">Confiança da torcida</div><div class="progress green" style="margin-top:10px"><span style="width:${state.fanConfidence}%"></span></div>`;cards.appendChild(d)}};
const _renderTopV032=renderTop;renderTop=function(){_renderTopV032();const top=$('.top-stats');if(top&&!$('#fanTop')){const s=document.createElement('span');s.className='pill';s.id='fanTop';s.innerHTML=`Torcida <b>${state.fanConfidence}%</b>`;top.insertBefore(s,top.firstChild)}};

const _windowStartV032=window.startMatch;window.startMatch=()=>{_windowStartV032();if(state.match&&state.match.minute===0){state.match.userXI.forEach(s=>{const p=player(s.playerId);state.match.fatigue[s.playerId]=clamp(100-(p?.fitness??100),0,75)});save();renderMatch()}};

// Nova temporada: envelhece uma vez, não sorteia OVR; a evolução é mensal e persistente.
startNextSeasonBaseV02=function(){const prev=state.season;state.history.push({type:'season',season:prev,summary:state.seasonSummary});state.seasonStartYear++;state.season=`${state.seasonStartYear}/${String(state.seasonStartYear+1).slice(-2)}`;state.date=`${state.seasonStartYear}-01-05`;state.manager.seasonDelta=0;state.seasonSummary=null;state.offseason=null;state.applications=[];state.incomingOffers=[];state.loans.filter(l=>l.active&&l.returnSeason<=state.seasonStartYear).forEach(l=>{const p=player(l.playerId);if(p){p.clubId=l.from;p.loanFrom=null}l.active=false});state.precontracts.filter(x=>x.executeSeason<=state.seasonStartYear).forEach(x=>{const p=player(x.playerId);if(p){p.clubId=x.to;p.contract=x.contract||3;p.wage=x.wage||p.wage;p.morale=82}});state.precontracts=state.precontracts.filter(x=>x.executeSeason>state.seasonStartYear);state.db.players.forEach(p=>{p.age++;p.contract=Math.max(0,p.contract-1);p.fitness=96;p.morale=clamp(p.morale+rnd(-2,3),45,95);resetPlayerSeason(p)});const currentIds=new Set(state.lineup?.xi?.map(x=>x.playerId)||[]),valid=currentIds.size===11&&[...currentIds].every(id=>player(id)?.clubId===state.clubId);if(!valid)state.lineup=autoLineup(state.clubId,state.formation);state.wageSpent=teamPlayers(state.clubId).reduce((s,p)=>s+p.wage,0);state.budget+=Math.round(club(state.clubId).budget*.35);state.lastDevelopmentMonth=state.date.slice(0,7);createSeasonStructure(state);state.news.push({date:state.date,title:`Temporada ${state.season}`,body:'Calendário atualizado. Jogadores envelheceram um ano; evolução e declínio seguem mensalmente.'});save()};

// save próprio da V0.4, com migração automática de V0.3.2.
save=function(){if(state)localStorage.setItem('soccerManagerV04',JSON.stringify(state))};
load=function(){try{return JSON.parse(localStorage.getItem('soccerManagerV04'))||JSON.parse(localStorage.getItem('soccerManagerV032'))||JSON.parse(localStorage.getItem('soccerManagerV02'))}catch(e){return null}};
