autoLineup=function(cid,formation='4-2-3-1',poolOverride=null){const pool=(poolOverride||teamPlayers(cid)).filter(p=>!v05IsInjured(p));return _autoLineupV04(cid,formation,pool)};

// --- desenvolvimento mensal mais perceptível e base viva ---
function v05GrowOne(p,amount,academy=false){if(!p||p.ovr>=99)return;const threshold=p.ovr>=(p.pot||99)?200:100;p.devProgress=(p.devProgress||0)+amount;while(p.devProgress>=threshold&&p.ovr<99){p.devProgress-=threshold;const before=p.ovr;v04AdjustAttrs(p,1);if(academy&&p.ovr>75){p.ovr=75;break}if(p.ovr===before)p.ovr=clamp(p.ovr+1,40,99)}}
function v05DevelopmentMonth(){const myId=state.clubId;for(const p of state.db.players){if(p.clubId==='free_agents')continue;const apps=p.season?.apps||0,age=p.age||25,mor=(p.morale||70)/100,form=(p.form||70)/100;const loan=!!p.loanFrom;let base=age<=20?30:age<=23?25:age<=26?19:age<=28?12:age<=30?5:0;if(loan&&age<=25){p.season.apps=(p.season.apps||0)+rnd(1,4);base+=9}if(base>0){const activity=clamp(.35+Math.min(1,apps/24)*.8+(loan?.25:0),.30,1.35),amount=base*activity*(.72+mor*.28)*(.78+form*.22);v05GrowOne(p,amount,false)}if(age>=30){let decline=(age===30?2:age<=33?4:age<=36?7:10);const active=Math.min(1,apps/22);decline*=1-active*.65;decline*=form>=.78?.72:1;p.declineProgress=(p.declineProgress||0)+decline;if(p.declineProgress>=100){p.declineProgress-=100;v04AdjustAttrs(p,-1)}}}
 const ac=state.academy;if(ac?.roster){for(const id of ac.roster){const p=player(id);if(!p)continue;p.youthApps=(p.youthApps||0)+rnd(2,5);const facility=1+(ac.level-1)*.055,potentialBoost=clamp(((p.pot||60)-p.ovr)/30,.25,1.5),ageBoost=p.age<=16?1.25:p.age<=18?1.1:.9;v05GrowOne(p,(20+rnd(2,12))*facility*potentialBoost*ageBoost,true);p.form=clamp(p.form+rnd(-2,4),55,94);p.morale=clamp(p.morale+rnd(-1,3),60,98)}}}
function v05RunMonthlyUntil(oldDate,newDate){let cur=new Date(oldDate+'T12:00:00');const end=new Date(newDate+'T12:00:00');let key=state.lastV05DevMonth||oldDate.slice(0,7);while(cur<=end){const k=cur.toISOString().slice(0,7);if(k!==key){v05DevelopmentMonth();key=k}cur.setDate(cur.getDate()+1)}state.lastV05DevMonth=key}

// --- lista de transferências, empréstimos e rescisão ---
window.v05ToggleList=(pid,type)=>{const p=player(pid);if(!p||p.clubId!==state.clubId)return;if(type==='transfer'){p.listed=!p.listed;if(p.listed)p.loanListed=false}else{p.loanListed=!p.loanListed;if(p.loanListed)p.listed=false}save();renderSquad();toast(p.listed?'Jogador listado para transferência.':p.loanListed?'Jogador listado para empréstimo.':'Jogador removido da lista.')};
window.v05ConfirmRelease=pid=>{const p=player(pid);if(!p||p.clubId!==state.clubId)return;const cost=Math.round((p.wage||0)*12*Math.max(0,p.contract||0)*.5);modal(`<div class="modal-head"><div><h2>Rescindir contrato</h2><div class="tiny muted">${p.name}</div></div><button onclick="closeModal()">✕</button></div><p>Você quer mesmo rescindir com <b>${p.name}</b>?</p><div class="summary-hero"><b>Custo da rescisão: ${brl(cost)}</b><div class="tiny muted">50% dos salários restantes (${p.contract} ano(s)).</div></div><div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px"><button onclick="closeModal()">Cancelar</button><button class="danger" onclick="v05Release('${p.id}',${cost})">Sim, rescindir</button></div>`)};
window.v05Release=(pid,cost)=>{const p=player(pid);if(!p)return;if(state.budget<cost)return toast('Caixa insuficiente para pagar a rescisão.');state.budget-=cost;p.clubId='free_agents';p.contract=0;p.freeAgent=true;p.listed=false;p.loanListed=false;p.morale=62;state.transactions.push({date:state.date,type:'Rescisão',player:p.name,value:cost});state.financeLedger=state.financeLedger||[];state.financeLedger.push({date:state.date,type:'Rescisão contratual',value:-cost,detail:p.name});state.lineup=autoLineup(state.clubId,state.formation);closeModal();save();renderAll();toast(`${p.name} agora está sem clube.`)};

const _playerDetailV04=playerDetail;
playerDetail=function(p){if(!p)return _playerDetailV04(p);let html=_playerDetailV04(p);const flag=v05Flag(p.nationality);html=html.replace(`<h2 style="margin:0">${p.name}</h2>`,`<h2 style="margin:0">${flag} ${p.name}</h2>`).replace(`<h3 style="margin:0">${p.name}</h3>`,`<h3 style="margin:0">${flag} ${p.name}</h3>`);if(p.clubId===state.clubId){html+=`<div class="card" style="margin-top:12px"><h3>Gestão do jogador</h3><div style="display:flex;flex-wrap:wrap;gap:7px"><button onclick="v05ToggleList('${p.id}','transfer')">${p.listed?'✓ Na lista de transferências':'Adicionar à lista de transferências'}</button><button onclick="v05ToggleList('${p.id}','loan')">${p.loanListed?'✓ Na lista de empréstimos':'Adicionar à lista de empréstimos'}</button><button class="danger" onclick="v05ConfirmRelease('${p.id}')">Rescindir contrato</button></div>${v05IsInjured(p)?`<div class="tiny" style="margin-top:8px;color:#ef4444">🏥 ${p.injuryName} • fora até ${fmtDate(p.injuryUntil)}</div>`:''}</div>`}return html};

