state && (state.marketFilters=state.marketFilters||{position:'ALL',status:'ALL'});
function v05MarketPool(){return state.db.players.filter(p=>p.clubId!==state.clubId&&p.clubId!=='academy').filter(p=>{const c=club(p.clubId);return p.freeAgent||p.clubId==='free_agents'||!c?.guest}).sort((a,b)=>b.ovr-a.ovr)}
function v05MatchesFilter(p){const f=state.marketFilters||{position:'ALL',status:'ALL'};if(f.position!=='ALL'&&!(p.positions||[p.pos]).includes(f.position))return false;if(f.status==='TRANSFER'&&!p.listed)return false;if(f.status==='LOAN'&&!p.loanListed)return false;if(f.status==='FREE'&&p.clubId!=='free_agents')return false;if(f.status==='EXPIRING'&&!(p.contract<=1&&p.clubId!=='free_agents'))return false;return true}
function v05MarketHtml(ps,open){return ps.slice(0,120).map(p=>{const free=p.clubId==='free_agents',c=club(p.clubId);return `<div class="market-card"><span class="pos">${p.pos}</span><div class="grow"><b>${v05Flag(p.nationality)} ${p.name}</b><div class="tiny muted">${free?'Sem clube':c.name} • ${p.age}a • OVR ${p.ovr} • ${free?'livre':brl(p.value)} • ${free?'sem contrato':`contrato ${p.contract}a`}${p.listed?' • 📌 transferência':''}${p.loanListed?' • 🔁 empréstimo':''}</div></div><div class="market-actions">${free?`<button onclick="v05OpenDeal('${p.id}','free')">Contratar livre</button>`:`<button ${open?'':'disabled'} onclick="v05OpenDeal('${p.id}','buy')">Comprar</button><button ${(open&&p.loanListed)||open?'':'disabled'} onclick="v05OpenDeal('${p.id}','loan')">Empréstimo</button><button ${p.contract<=1?'':'disabled'} onclick="v05OpenDeal('${p.id}','pre')">Pré-contrato</button>`}</div></div>`}).join('')||'<p class="muted">Nenhum jogador encontrado com esses filtros.</p>'}
renderTransfers=function(){state.marketFilters=state.marketFilters||{position:'ALL',status:'ALL'};const open=transferWindowOpen(),offers=state.incomingOffers||[],pool=v05MarketPool();$('#transfers').innerHTML=`<div class="page-head"><div><h1>Transferências</h1><p>Compra, empréstimo, pré-contrato e passes livres.</p></div><span class="tag">${open?'JANELA ABERTA':'JANELA FECHADA'}</span></div><div class="grid grid-3"><div class="card"><div class="metric">${brl(state.budget)}</div><div class="metric-label">Caixa</div></div><div class="card"><div class="metric">${pool.filter(p=>p.clubId==='free_agents').length}</div><div class="metric-label">Passes livres</div></div><div class="card"><div class="metric">${offers.length}</div><div class="metric-label">Propostas recebidas</div></div></div>${offers.length?`<div class="card" style="margin-top:13px"><h3>Propostas recebidas</h3>${offers.map(o=>{const p=player(o.playerId);return `<div class="market-card"><div class="grow"><b>${club(o.fromClubId)?.name||'Clube'} → ${p?.name||'Jogador'}</b><div class="tiny muted">${o.type==='loan'?'Empréstimo':'Transferência'} • ${brl(o.value||0)}</div></div><button class="success" onclick="acceptIncoming('${o.id}')">Aceitar</button><button onclick="rejectIncoming('${o.id}')">Recusar</button></div>`}).join('')}</div>`:''}<div class="card" style="margin-top:13px"><div style="display:flex;gap:8px;align-items:end;flex-wrap:wrap"><div class="field grow"><label>Buscar</label><input id="marketSearch" placeholder="Jogador ou clube..."></div><div class="field"><label>Posição</label><select id="marketPos"><option value="ALL">Todas</option>${V03_POSITIONS.map(x=>`<option ${state.marketFilters.position===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Tipo</label><select id="marketStatus"><option value="ALL">Todos</option><option value="TRANSFER" ${state.marketFilters.status==='TRANSFER'?'selected':''}>Lista de transferências</option><option value="LOAN" ${state.marketFilters.status==='LOAN'?'selected':''}>Lista de empréstimos</option><option value="FREE" ${state.marketFilters.status==='FREE'?'selected':''}>Sem contrato</option><option value="EXPIRING" ${state.marketFilters.status==='EXPIRING'?'selected':''}>Fim de contrato</option></select></div></div><div id="marketList" style="margin-top:8px"></div></div>`;const draw=()=>{const q=($('#marketSearch').value||'').toLowerCase();$('#marketList').innerHTML=v05MarketHtml(pool.filter(p=>v05MatchesFilter(p)&&(!q||p.name.toLowerCase().includes(q)||(club(p.clubId)?.name||'sem clube').toLowerCase().includes(q))),open)};$('#marketSearch').oninput=draw;$('#marketPos').onchange=e=>{state.marketFilters.position=e.target.value;save();draw()};$('#marketStatus').onchange=e=>{state.marketFilters.status=e.target.value;save();draw()};draw()};

window.v05OpenDeal=(pid,type)=>{const p=player(pid),c=club(p.clubId),free=type==='free';if(!p)return;const baseW=Math.max(2000,p.wage||Math.round(p.ovr*p.ovr*12));modal(`<div class="modal-head"><div><h2>${free?'Contratar passe livre':type==='loan'?'Negociar empréstimo':type==='pre'?'Pré-contrato':'Negociar transferência'} • ${p.name}</h2><div class="tiny muted">${free?'Sem clube':c.name} • OVR ${p.ovr} • ${v05Flag(p.nationality)} ${p.nationality||''}</div></div><button onclick="closeModal()">✕</button></div>${!free&&type==='buy'?`<div class="field"><label>Valor da proposta</label><input id="dealFee" type="number" value="${Math.round(p.value*(p.listed?.82:1))}"></div>`:''}${type==='loan'?`<div class="grid grid-2"><div class="field"><label>Taxa de empréstimo</label><input id="dealFee" type="number" value="${Math.round(p.value*.035)}"></div><div class="field"><label>Duração (meses)</label><select id="dealMonths"><option>6</option><option selected>12</option><option>24</option></select></div></div><div class="check-row"><span>Opção de compra</span><input type="checkbox" id="dealOption"></div>`:''}<div class="grid grid-2"><div class="field"><label>Salário mensal</label><input id="dealWage" type="number" value="${Math.round(baseW*(free?1.05:1.08))}"></div><div class="field"><label>${type==='loan'?'Luvas':'Contrato (anos)'}</label>${type==='loan'?`<input id="dealBonus" type="number" value="${Math.round(baseW*1.5)}">`:`<select id="dealYears"><option>1</option><option>2</option><option selected>3</option><option>4</option><option>5</option></select>`}</div></div>${type!=='loan'?`<div class="field"><label>Luvas</label><input id="dealBonus" type="number" value="${Math.round(baseW*2.5)}"></div>`:''}<button class="primary" onclick="v05SubmitDeal('${p.id}','${type}')">Enviar proposta</button>`)};
window.v05SubmitDeal=(pid,type)=>{const p=player(pid);if(!p)return;const wage=+$('#dealWage')?.value||p.wage,bonus=+$('#dealBonus')?.value||0,years=+$('#dealYears')?.value||3,fee=+$('#dealFee')?.value||0;let chance=.50+v05Diff().transfer+(p.morale||70)/500;if(type==='free'){chance+=wage/Math.max(1,p.wage)*.12;if(bonus>p.wage*2)chance+=.08;if(Math.random()>clamp(chance,.18,.95))return toast('O jogador recusou os termos pessoais.');if(state.budget<bonus)return toast('Caixa insuficiente para as luvas.');state.budget-=bonus;p.clubId=state.clubId;p.contract=years;p.wage=wage;p.freeAgent=false;p.morale=80;p.listed=false;p.loanListed=false;state.lineup=autoLineup(state.clubId,state.formation);closeModal();save();renderAll();return toast('Passe livre contratado!')}
 if(type==='pre'){if(p.contract>1)return toast('Jogador não está em fim de contrato.');chance+=wage/Math.max(1,p.wage)*.10;if(Math.random()>clamp(chance,.15,.93))return toast('Jogador recusou o pré-contrato.');state.precontracts.push({playerId:p.id,to:state.clubId,executeSeason:state.seasonStartYear+1,contract:years,wage,bonus});state.budget-=Math.min(state.budget,bonus);closeModal();save();return toast('Pré-contrato acertado!')}
 const seller=club(p.clubId);if(type==='buy'){const ask=p.value*(p.listed?.78:1);chance+=((fee/Math.max(1,ask))-1)*.65;if(Math.random()>clamp(chance,.05,.96))return toast('Clube/jogador recusou a proposta.');if(state.budget<fee+bonus)return toast('Caixa insuficiente.');state.budget-=fee+bonus;p.clubId=state.clubId;p.contract=years;p.wage=wage;p.morale=78;p.listed=false;p.loanListed=false;state.lineup=autoLineup(state.clubId,state.formation);closeModal();save();renderAll();return toast(`${p.name} contratado!`)}
 if(type==='loan'){const months=+$('#dealMonths').value||12,opt=$('#dealOption').checked;chance+=(p.loanListed?.18:0)+((fee/(Math.max(1,p.value*.04)))-1)*.2;if(Math.random()>clamp(chance,.08,.93))return toast('O clube recusou os termos do empréstimo.');if(state.budget<fee+bonus)return toast('Caixa insuficiente.');state.budget-=fee+bonus;state.loans.push({id:uid(),playerId:p.id,from:p.clubId,to:state.clubId,active:true,months,option:opt?Math.round(p.value*.95):null,returnSeason:state.seasonStartYear+(months>=18?2:1)});p.loanFrom=p.clubId;p.clubId=state.clubId;p.wage=wage;p.morale=76;state.lineup=autoLineup(state.clubId,state.formation);closeModal();save();renderAll();toast('Empréstimo fechado!')}};

// IA de mercado mais viva e propostas direcionadas às listas do usuário.
aiMarketTick=function(){const open=transferWindowOpen();const my=teamPlayers(state.clubId);if(open){for(const p of my){const listed=p.listed||p.loanListed;if(listed&&Math.random()<(p.listed?.16:.13)){const buyers=state.db.clubs.filter(c=>!c.guest&&c.id!==state.clubId&&c.id!=='free_agents'&&Math.abs(c.rep-p.ovr)<18);const b=pick(buyers);if(b&&!state.incomingOffers.some(o=>o.playerId===p.id)){state.incomingOffers.push({id:uid(),playerId:p.id,fromClubId:b.id,type:p.loanListed?'loan':'sale',value:p.loanListed?Math.round(p.value*.03):Math.round(p.value*rnd(72,103)/100)})}}}
 const aiPlayers=state.db.players.filter(p=>p.clubId!==state.clubId&&p.clubId!=='free_agents'&&!club(p.clubId)?.guest);for(let k=0;k<rnd(1,4);k++){const p=pick(aiPlayers);if(!p)continue;if(Math.random()<.10){p.listed=true;p.loanListed=false}else if(p.age<=23&&Math.random()<.11){p.loanListed=true;p.listed=false}if((p.listed||p.loanListed)&&Math.random()<.12){const targets=state.db.clubs.filter(c=>!c.guest&&c.id!==p.clubId&&c.id!==state.clubId&&c.id!=='free_agents'&&Math.abs(c.rep-p.ovr)<15);const to=pick(targets);if(to){if(p.loanListed){p.loanFrom=p.clubId;p.clubId=to.id;p.morale=75}else{p.clubId=to.id;p.contract=rnd(2,5);p.morale=80}p.listed=false;p.loanListed=false}}} }
 // renovações da IA
 for(const p of state.db.players.filter(p=>p.clubId!==state.clubId&&p.clubId!=='free_agents'&&!club(p.clubId)?.guest&&p.contract<=1)){if(Math.random()<.07){p.contract=rnd(2,4);p.morale=clamp(p.morale+3,0,100)}}};

// --- energia de partida: queda menor e não uniforme ---
matchStep=function(){const m=state.match,f=state.fixtures.find(x=>x.id===m?.fixtureId);if(!m||m.finished||m.subModal)return;m.minute++;m.userXI.forEach(s=>{const p=player(s.playerId);if(!p)return;const ageFactor=p.age>=36?1.32:p.age>=32?1.18:p.age<=22?.86:1,phys=clamp(1.14-(p.attrs?.fis||70)/300,.78,1.08),press=1+(state.pressing-50)/260,tempo=1+(state.tempo-50)/300,inc=(.115+Math.random()*.045)*ageFactor*phys*press*tempo;m.fatigue[p.id]=clamp((m.fatigue[p.id]||0)+inc,0,100)});animatePitch();const hs=matchTeamStrength(f.home),as=matchTeamStrength(f.away),meHome=f.home===state.clubId;const mental={Ultradefensivo:{atk:-.23,def:.21,ch:.72},Defensivo:{atk:-.10,def:.10,ch:.88},Equilibrado:{atk:0,def:0,ch:1},Ofensivo:{atk:.12,def:-.10,ch:1.15},Ultraofensivo:{atk:.25,def:-.22,ch:1.34}}[m.mentality]||{atk:0,def:0,ch:1};let myMod=(state.pressing-55)/420+(state.tempo-55)/450+(state.line-50)/850;let attH=hs*(1+(meHome?mental.atk+myMod:0)),attA=as*(1+(!meHome?mental.atk+myMod:0));if(meHome)attA*=1-mental.def;else attH*=1-mental.def;let pH=attH/(attH+attA);m.stats.posH=clamp(Math.round(45+(pH-.5)*65+rnd(-2,2)),31,69);m.stats.posA=100-m.stats.posH;const chanceRate=.125*(meHome?mental.ch:1);if(Math.random()<chanceRate+(state.tempo-50)/1100){const homeAttack=Math.random()<pH,att=homeAttack?attH:attA,def=homeAttack?as:hs,quality=(att/Math.max(1,def))*Math.random(),s=m.stats;homeAttack?s.shotsH++:s.shotsA++;const xg=clamp(.03+quality*.16+Math.random()*.11,.025,.39);homeAttack?s.xgH+=xg:s.xgA+=xg;const on=Math.random()<.38+quality*.13;if(on){homeAttack?s.onH++:s.onA++;if(Math.random()<xg*(.68+Math.random()*.24)){homeAttack?m.home++:m.away++;const cid=homeAttack?f.home:f.away,sc=scorerFor(cid),asst=assistFor(cid,sc.id);m.goalEvents.push({min:m.minute,clubId:cid,scorerId:sc.id,assistId:asst?.id||null});m.comments.push({min:m.minute,text:`GOL do ${club(cid).name}! ${sc.name} marcou.`});toast(`⚽ ${sc.name}`)}}}if(m.minute===45&&!m.halfTimeDone){m.halfTimeDone=true;m.comments.push({min:45,text:'Intervalo. Hora de ajustar a equipe.'});state.match=m;save();updateMatchDom();openSubs(true);return}if(m.minute>=90){finishMatch();return}state.match=m;save();updateMatchDom()};
fatigueHtml=function(m){if(!m)return '<p class="muted tiny">Energia calculada ao iniciar a partida.</p>';return m.userXI.map(s=>{const p=player(s.playerId),fat=Math.round(m.fatigue[p.id]||0),energy=clamp(100-fat,0,100),cls=energy<=35?'high':energy<=60?'mid':'';return `<div class="fatigue-line"><span><b>${p.name}</b> <span class="tiny muted">${s.slotPos}</span></span><span class="fatigue-badge ${cls}">energia ${energy}%</span></div>`}).join('')};

// --- simulação inteligente pelo calendário ---
function v05SmartXI(cid){const ps=teamPlayers(cid).filter(p=>!v05IsInjured(p));const score=p=>p.ovr+(p.fitness-75)*.16+(p.morale-70)*.035+(p.form-70)*.05-(p.fitness<68?8:0);const pool=ps.sort((a,b)=>score(b)-score(a));return autoLineup(cid,state.formation||'4-2-3-1',pool)}
const _v04TeamQualityBase=v04TeamQuality;
v04TeamQuality=function(cid){let q=_v04TeamQualityBase(cid);if(cid===state.clubId)q*=v05Diff().strength;return q};
function v05RecoverBetween(days){if(days<=0)return;for(const p of teamPlayers(state.clubId)){const ageMul=p.age>=35?.76:p.age>=31?.88:p.age<=23?1.12:1,rate=(2.4+(p.attrs?.fis||70)/55)*ageMul;p.fitness=clamp(p.fitness+rate*days,25,100)}}
autoSimUserFixture=function(f){if(f.played)return;const line=v05SmartXI(state.clubId),ids=line.xi.map(x=>x.playerId);const oldLine=state.lineup;state.lineup=line;simulateFixture(f);state.lineup=oldLine;for(const id of ids){const p=player(id);if(p){const age=p.age>=35?1.25:p.age<=22?.88:1;p.fitness=clamp(p.fitness-(rnd(8,15)*age),35,100)}}const home=f.home===state.clubId,my=home?f.score.home:f.score.away,opp=home?f.score.away:f.score.home,result=my>opp?'win':my<opp?'loss':'draw';state.manager.played++;state.manager.gf+=my;state.manager.ga+=opp;if(result==='win')state.manager.wins++;else if(result==='loss')state.manager.losses++;else state.manager.draws++;updateStreak(result);state.clubConfidence=clamp(state.clubConfidence+(result==='win'?3:result==='loss'?-3:1),0,100);state.history.push({date:f.date,clubId:state.clubId,fixtureId:f.id,result,score:`${my}-${opp}`});state.news.unshift({date:f.date,title:`Simulação: ${club(f.home).name} ${f.score.home} x ${f.score.away} ${club(f.away).name}`,body:'Escalação automática inteligente considerou energia, lesões, forma e profundidade.'})};
advanceGameDays=function(target,includeUser=true){if(state.match&&!state.match.finished)return toast('Finalize a partida antes.');const start=state.date;if(target<=start)return;let last=start;const games=state.fixtures.filter(f=>!f.played&&f.date>start&&f.date<=target).sort((a,b)=>a.date.localeCompare(b.date));for(const f of games){const gap=Math.max(0,Math.round((new Date(f.date)-new Date(last))/86400000));v05RecoverBetween(gap);state.date=f.date;if(f.home===state.clubId||f.away===state.clubId){if(includeUser)autoSimUserFixture(f)}else simulateFixture(f);last=f.date;maybeAdvanceCup();checkCompetitionFinish()}const tail=Math.max(0,Math.round((new Date(target)-new Date(last))/86400000));v05RecoverBetween(tail);state.date=target;v05RunMonthlyUntil(start,target);v05InjuryTick(Math.max(1,Math.round((new Date(target)-new Date(start))/86400000)));for(let i=0;i<Math.max(1,Math.ceil((new Date(target)-new Date(start))/604800000));i++)aiMarketTick();processScoutMissions();generateYouthIntake(false);checkSeasonEnd();save();renderAll();toast(`Avançado até ${fmtDate(target)}.`)};

// --- resumo de temporada por divisão e arquivo histórico ---
function v05ArchiveSeason(){state.seasonArchives=state.seasonArchives||[];if(state.seasonArchives.some(x=>x.season===state.season))return;const b=state.seasonBaseline||{played:0,wins:0,draws:0,losses:0,gf:0,ga:0,titles:0};state.seasonArchives.push({season:state.season,played:state.manager.played-b.played,wins:state.manager.wins-b.wins,draws:state.manager.draws-b.draws,losses:state.manager.losses-b.losses,gf:state.manager.gf-b.gf,ga:state.manager.ga-b.ga,titles:state.manager.titles-b.titles,clubId:state.clubId});}
finishSeason=function(){checkCompetitionFinish();state.seasonEnded=true;const userCompId=v05LeagueId(),tbl=sortedTable(userCompId),champ=tbl[0]?.clubId,topSc=compLeaders(userCompId,'goals')[0],mvp=compLeaders(userCompId,'rating')[0];let relegated=[],promoted=[];if(userCompId==='brA'){const tb=sortedTable('brB');relegated=tbl.slice(-4).map(x=>x.clubId);promoted=tb.slice(0,4).map(x=>x.clubId);state.qualifications={};tbl.slice(0,4).forEach(r=>state.qualifications[r.clubId]='libertadores');tbl.slice(4,8).forEach(r=>state.qualifications[r.clubId]='sudamericana');relegated.forEach(id=>club(id).division='B');promoted.forEach(id=>club(id).division='A')}else if(userCompId==='brB'){relegated=tbl.slice(-4).map(x=>x.clubId);promoted=tbl.slice(0,4).map(x=>x.clubId)}else{relegated=tbl.slice(-3).map(x=>x.clubId)}state.seasonSummary={season:state.season,userCompId,champion:champ,relegated,promoted,topScorer:topSc?{name:topSc.p.name,goals:topSc.s.goals,clubId:topSc.p.clubId}:null,mvp:mvp?{name:mvp.p.name,rating:(mvp.s.ratingSum/mvp.s.ratingApps),clubId:mvp.p.clubId}:null};if(champ===state.clubId){state.manager.titles++;state.manager.rating=clamp(state.manager.rating+.35,1,10)}v05ArchiveSeason();state.offseason={active:true,endDate:addDays(state.date,30),summarySeen:false};showSeasonSummary();save();renderTop()};
showSeasonSummary=function(){const s=state.seasonSummary;if(!s)return;const c=comp(s.userCompId),label=c?.name||'Competição';modal(`<div class="modal-head"><div><h2>🏁 Fim da temporada ${s.season}</h2><div class="tiny muted">A janela pós-temporada está aberta por 30 dias.</div></div><button onclick="closeSeasonSummary()">✕</button></div><div class="season-summary"><div class="summary-hero"><div class="metric" style="font-size:24px">🏆 ${club(s.champion)?.name||'—'}</div><div class="metric-label">Campeão • ${label}</div></div><div class="grid grid-2"><div class="card"><h3>Artilheiro</h3>${s.topScorer?`<b>${s.topScorer.name}</b><div class="tiny muted">${club(s.topScorer.clubId).name} • ${s.topScorer.goals} gols</div>`:'—'}</div><div class="card"><h3>MVP</h3>${s.mvp?`<b>${s.mvp.name}</b><div class="tiny muted">${club(s.mvp.clubId).name} • nota ${s.mvp.rating.toFixed(2)}</div>`:'—'}</div></div><div class="grid grid-2"><div class="card"><h3>${s.userCompId==='brB'?'Últimos colocados':'Rebaixados'}</h3>${s.relegated.map(id=>`<div>${club(id).name}</div>`).join('')||'—'}</div><div class="card"><h3>Promovidos</h3>${s.promoted.map(id=>`<div>${club(id).name}</div>`).join('')||'<span class="muted">Não aplicável</span>'}</div></div><div class="card"><h3>Tabela final • ${label}</h3>${tableHtml(s.userCompId)}</div></div>`)};

const _renderDashboardV04=renderDashboard;
renderDashboard=function(){_renderDashboardV04();const host=$('#dashboard');if(!host)return;const arr=(state.seasonArchives||[]).slice().reverse();const box=document.createElement('div');box.className='card';box.style.marginTop='13px';box.innerHTML=`<h3>Temporadas do técnico</h3>${arr.length?arr.map(x=>`<div class="market-card"><div class="grow"><b>${x.season}</b><div class="tiny muted">${club(x.clubId)?.name||''}</div></div><span>${x.wins}V • ${x.draws}E • ${x.losses}D • ${x.gf} GP • ${x.ga} GC • ${x.titles} título(s)</span></div>`).join(''):'<p class="muted">A temporada atual será arquivada ao terminar.</p>'}`;host.appendChild(box)};

