renderAcademy=function(){_renderAcademyV04();const h=$('#academy .page-head p');if(h)h.textContent='Relatórios mensais • atletas contratados evoluem em jogos internos Sub-14/Sub-16/Sub-18/Sub-21.';$$('#academy .market-card').forEach(el=>{const text=el.textContent;const p=(state.academy.roster||[]).map(player).find(x=>x&&text.includes(x.name));if(p){const meta=el.querySelector('.tiny.muted');if(meta)meta.textContent=`${p.age} anos • OVR ${p.ovr} • POT ${p.pot} • jogos de base ${p.youthApps||0} • progresso interno ativo`}})};

// --- configurações com dificuldade e lesões ---
renderSettings=function(){const ac=state.academy;$('#settings').innerHTML=`<div class="page-head"><div><h1>Configurações</h1><p>Preferências da carreira e ferramentas de desenvolvedor.</p></div></div><div class="grid grid-2"><div class="card"><h3>Jogabilidade</h3><div class="field"><label>Dificuldade</label><select id="diffSelect"><option value="easy" ${state.difficulty==='easy'?'selected':''}>Fácil</option><option value="normal" ${state.difficulty==='normal'?'selected':''}>Normal</option><option value="hard" ${state.difficulty==='hard'?'selected':''}>Difícil</option></select></div><div class="check-row"><div><b>Lesões</b><div class="tiny muted">Eventos raros com gravidades e tempos de recuperação diferentes.</div></div><input id="injToggle" type="checkbox" ${state.injuriesEnabled?'checked':''}></div><h3 style="margin-top:18px">Aparência</h3><button onclick="document.getElementById('themeToggle').click()">Alternar modo claro/escuro</button></div><div class="card"><h3>Desenvolvedor</h3>${state.developerUnlocked?`<div class="dev-box card"><div class="field"><label>Dinheiro</label><input id="devMoney" type="number" value="${state.budget}"></div><div class="field"><label>Nível da base (1-10)</label><input id="devAcademy" type="number" min="1" max="10" value="${ac.level}"></div><div class="field"><label>Ranking do manager (1-10)</label><input id="devRating" type="number" min="1" max="10" step="0.1" value="${state.manager.rating}"></div><button class="primary" onclick="applyDev()">Aplicar</button></div>`:`<div class="field"><label>Código</label><input id="devCode" type="password" placeholder="Digite o código"></div><button onclick="unlockDev()">Desbloquear</button>`}</div></div>`;$('#diffSelect').onchange=e=>{state.difficulty=e.target.value;save();toast('Dificuldade alterada.')};$('#injToggle').onchange=e=>{state.injuriesEnabled=e.target.checked;save()}};

// --- competições: seleção global e grupos da Sula ---
const _tableHtmlV04=tableHtml;
tableHtml=function(cid,mini=false){const c=comp(cid);if(c?.type==='groups'){return Object.entries(c.groups||{}).map(([g,teams])=>`<div class="card" style="margin-bottom:8px"><h3>Grupo ${g}</h3>${teams.map((n,i)=>`<div class="leader"><div class="rank">${i+1}</div><div class="grow"><b>${n}</b></div></div>`).join('')}</div>`).join('')}return _tableHtmlV04(cid,mini)};
renderCompetitions=function(){const ids=Object.keys(state.competitions),want=state.selectedCompetition&&state.competitions[state.selectedCompetition]?state.selectedCompetition:v05LeagueId();state.selectedCompetition=want;const c=comp(want);$('#competitions').innerHTML=`<div class="page-head"><div><h1>Competições</h1><p>Brasil, Inglaterra, Espanha e continental.</p></div><div style="width:280px"><select id="compSelect">${ids.map(id=>`<option value="${id}" ${id===want?'selected':''}>${state.competitions[id].name}</option>`).join('')}</select></div></div><div class="comp-layout"><div class="card"><h3>${c.name}</h3><div style="margin-top:11px">${tableHtml(want)}</div></div>${c.type==='groups'?'':`<div class="grid">${leadersBlock(want,'goals','⚽ Artilharia')}${leadersBlock(want,'assists','🎯 Assistências')}${leadersBlock(want,'rating','⭐ Melhor nota média')}</div>`}</div>`;$('#compSelect').onchange=e=>{state.selectedCompetition=e.target.value;save();renderCompetitions()}};

