const _startNextSeasonV04=startNextSeasonBaseV02;
startNextSeasonBaseV02=function(){_startNextSeasonV04();state.seasonBaseline={played:state.manager.played,wins:state.manager.wins,draws:state.manager.draws,losses:state.manager.losses,gf:state.manager.gf,ga:state.manager.ga,titles:state.manager.titles};state.lastV05DevMonth=state.date.slice(0,7);save()};

// --- migração/save V0.5 ---
const _hydrateV04=hydrateLoadedState;
hydrateLoadedState=function(){try{_hydrateV04()}catch(e){console.warn(e)}state.version='0.5';v05PatchExistingDb();state.difficulty=state.difficulty||'normal';state.injuriesEnabled=state.injuriesEnabled!==false;state.marketFilters=state.marketFilters||{position:'ALL',status:'ALL'};state.seasonArchives=state.seasonArchives||[];state.seasonBaseline=state.seasonBaseline||{played:state.manager.played||0,wins:state.manager.wins||0,draws:state.manager.draws||0,losses:state.manager.losses||0,gf:state.manager.gf||0,ga:state.manager.ga||0,titles:state.manager.titles||0};state.lastV05DevMonth=state.lastV05DevMonth||state.date.slice(0,7);if(state.manager.played===0){state.clubConfidence=100;state.fanConfidence=100}if(!state.competitions?.pl){const ids=state.db.clubs.filter(c=>c.division==='PL').map(c=>c.id);state.competitions.pl={id:'pl',name:'Liga Inglesa',type:'league',clubIds:ids,table:makeLeagueTable(ids),finished:false,champion:null};state.fixtures.push(...createRoundRobin(ids,'pl',`${state.seasonStartYear}-08-21`,true))}if(!state.competitions?.laliga){const ids=state.db.clubs.filter(c=>c.division==='LL').map(c=>c.id);state.competitions.laliga={id:'laliga',name:'Liga Espanhola',type:'league',clubIds:ids,table:makeLeagueTable(ids),finished:false,champion:null};state.fixtures.push(...createRoundRobin(ids,'laliga',`${state.seasonStartYear}-08-15`,true))}if(!state.competitions?.sula2026)state.competitions.sula2026={id:'sula2026',name:'Copa Sul-Continental 2026',type:'groups',groups:V05_SULA_GROUPS,finished:state.seasonStartYear>2026};state.fixtures.sort((a,b)=>a.date.localeCompare(b.date));if(state.lineup){const injured=teamPlayers(state.clubId).filter(v05IsInjured).map(p=>p.id);if(injured.some(id=>state.lineup.xi.some(x=>x.playerId===id)||state.lineup.bench.includes(id)))state.lineup=autoLineup(state.clubId,state.formation)}};
const _initialStateV04=initialState;
initialState=function(manager,clubId,opts){const s=_initialStateV04(manager,clubId,opts);state=s;v05PatchExistingDb();s.version='0.5';s.difficulty='normal';s.injuriesEnabled=true;s.marketFilters={position:'ALL',status:'ALL'};s.seasonArchives=[];s.seasonBaseline={played:0,wins:0,draws:0,losses:0,gf:0,ga:0,titles:0};s.lastV05DevMonth=s.date.slice(0,7);s.clubConfidence=100;s.fanConfidence=100;createSeasonStructure(s);s.lineup=autoLineup(s.clubId,s.formation);return s};
save=function(){if(state)localStorage.setItem('soccerManagerV05',JSON.stringify(state))};
load=function(){try{return JSON.parse(localStorage.getItem('soccerManagerV05'))||JSON.parse(localStorage.getItem('soccerManagerV04'))||JSON.parse(localStorage.getItem('soccerManagerV032'))||JSON.parse(localStorage.getItem('soccerManagerV02'))}catch(e){return null}};

