setupClubOptions=function(){$('#clubSelect').innerHTML=BASE_DATA.clubs.filter(c=>!c.guest&&c.id!=='free_agents').map(c=>`<option value="${c.id}">${c.name} — ${c.division==='A'?'Liga Nacional Série A':c.division==='B'?'Liga Nacional Série B':c.division==='PL'?'Liga Inglesa':c.division==='LL'?'Liga Espanhola':'Liga'}</option>`).join('')};
setupClubOptions();
const note=document.querySelector('.db-note');if(note)note.textContent='Universo fictício: clubes, jogadores, estádios e competições usam nomes inspirados no futebol real, sem licença oficial. Brasil (Séries A e B), Liga Inglesa, Liga Espanhola e passes livres. OVR, potencial, valores e salários são parâmetros de jogo.';
/* V0.5 hotfixes de consistência */
currentStanding=function(){const id=v05LeagueId(),t=sortedTable(id),i=t.findIndex(r=>r.clubId===state.clubId);return i>=0?{...t[i],pos:i+1}:null};
checkSeasonEnd=function(){if(state.seasonEnded||state.offseason?.active)return;const id=v05LeagueId(),fs=state.fixtures.filter(f=>f.compId===id);if(fs.length&&fs.every(f=>f.played))finishSeason()};
startNextSeason=function(){startNextSeasonBaseV02();state.academy.candidates=[];generateYouthIntake(true);Object.assign(AGE_FIXES,V05_AGE_FIX);save()};
const _v05SwapBase=v04SwapPlayers;
v04SwapPlayers=function(a,b){const A=v04Locate(a),B=v04Locate(b),pa=player(a),pb=player(b);if((v05IsInjured(pa)&&(B?.area==='xi'||B?.area==='bench'))||(v05IsInjured(pb)&&(A?.area==='xi'||A?.area==='bench')))return toast('Jogador lesionado só pode ficar entre os não relacionados.');return _v05SwapBase(a,b)};
const _v05MoveBase=window.v04MoveToPos;
window.v04MoveToPos=(pid,pos)=>{const p=player(pid);if(v05IsInjured(p))return toast('Jogador lesionado não pode ser relacionado.');return _v05MoveBase(pid,pos)};

/* V0.5.0b: promoção/rebaixamento global + resumo da divisão do usuário */
finishSeason=function(){
 checkCompetitionFinish();state.seasonEnded=true;
 const userCompId=v05LeagueId(),userTable=sortedTable(userCompId),champ=userTable[0]?.clubId;
 const topSc=compLeaders(userCompId,'goals')[0],mvp=compLeaders(userCompId,'rating')[0];
 const ta=sortedTable('brA'),tb=sortedTable('brB'),aDown=ta.slice(-4).map(x=>x.clubId),bUp=tb.slice(0,4).map(x=>x.clubId);
 let relegated=userCompId==='brA'?aDown:userCompId==='brB'?userTable.slice(-4).map(x=>x.clubId):userTable.slice(-3).map(x=>x.clubId);
 let promoted=userCompId==='brB'?bUp:[];
 state.seasonSummary={season:state.season,userCompId,champion:champ,relegated,promoted,topScorer:topSc?{name:topSc.p.name,goals:topSc.s.goals,clubId:topSc.p.clubId}:null,mvp:mvp?{name:mvp.p.name,rating:(mvp.s.ratingSum/mvp.s.ratingApps),clubId:mvp.p.clubId}:null};
 state.qualifications={};ta.slice(0,4).forEach(r=>state.qualifications[r.clubId]='libertadores');ta.slice(4,8).forEach(r=>state.qualifications[r.clubId]='sudamericana');
 aDown.forEach(id=>{const c=club(id);if(c)c.division='B'});bUp.forEach(id=>{const c=club(id);if(c)c.division='A'});
 if(champ===state.clubId){state.manager.titles++;state.manager.rating=clamp(state.manager.rating+.35,1,10)}
 v05ArchiveSeason();state.offseason={active:true,endDate:addDays(state.date,30),summarySeen:false};state.news.unshift({date:state.date,title:`Fim da temporada ${state.season}`,body:`${club(champ)?.name||'O campeão'} venceu ${comp(userCompId)?.name||'a competição'}.`});showSeasonSummary();save();renderTop();
};

